/// Enemy behaviour mode this frame, derived from the stealth state: an unaware tank patrols and only
/// scans, a searching one sweeps toward a last-known area, a tracking one lays on and fires the
/// player. This is the whole diegetic tell — the turret only swings onto you once you've been made.
#[derive(Copy, Clone, PartialEq, Eq)]
enum AiMode {
    Patrol, // Unaware — slow advance, scanning, never fires the player
    Search, // Searching — hunts the platoon's last-known area, sweeping the turret, never fires
    Track,  // spotted / Engaged — flanks + fires the player (the classic combat behaviour)
}

/// ABSITZEN: which body the player is driving — the Tiger, or the dismounted soldier.
#[derive(Clone, Copy, PartialEq)]
pub enum Mode {
    Tank,
    Foot,
}

/// One policy decision sampled from the live physical campaign.  The runner pairs successive
/// records for the same `(role, agent_id)` into `kessel.foot_transition.v1` DAgger rows.
#[derive(Clone, Copy, Debug)]
pub(crate) struct CampaignFootDecision {
    pub step: u32,
    pub site_id: u32,
    pub agent_id: u32,
    pub role: PolicyRole,
    pub observation: FootObservation,
    pub action: FootAction,
    pub expert_action: FootAction,
}

fn cached_default_foot_policy(role: PolicyRole) -> Option<FootPolicy> {
    static TIGER: OnceLock<Option<FootPolicy>> = OnceLock::new();
    static SOVIET: OnceLock<Option<FootPolicy>> = OnceLock::new();
    static GERMAN: OnceLock<Option<FootPolicy>> = OnceLock::new();
    let cache = match role {
        PolicyRole::TigerCrew => &TIGER,
        PolicyRole::SovietRifle => &SOVIET,
        PolicyRole::GermanRifle => &GERMAN,
    };
    cache
        .get_or_init(|| match FootPolicy::load(role.checkpoint_path(), role) {
            Ok((policy, metadata)) => {
                println!(
                    "[foot-ai] loaded {} KSL2 generation {} score {:.3} from {}",
                    role.label(),
                    metadata.generation,
                    metadata.fitness,
                    role.checkpoint_path(),
                );
                Some(policy)
            }
            Err(error) => {
                eprintln!(
                    "[foot-ai] {} checkpoint unavailable/invalid at {} ({error}); scripted expert fallback active",
                    role.label(),
                    role.checkpoint_path(),
                );
                None
            }
        })
        .clone()
}

