fn campaign_loot_candidates(act: u8, kind: PickupKind) -> &'static [Vec2] {
    match (act, kind) {
        (1, PickupKind::Ammo) => ACT1_LOOT_AMMO,
        (1, PickupKind::Fuel) => ACT1_LOOT_FUEL,
        (1, PickupKind::Medical) => ACT1_LOOT_MEDICAL,
        (1, PickupKind::Cigarettes) => ACT1_LOOT_CIGARETTES,
        (2, PickupKind::Ammo) => ACT2_LOOT_AMMO,
        (2, PickupKind::Fuel) => ACT2_LOOT_FUEL,
        (2, PickupKind::Medical) => ACT2_LOOT_MEDICAL,
        (2, PickupKind::Cigarettes) => ACT2_LOOT_CIGARETTES,
        (3, PickupKind::Ammo) => ACT3_LOOT_AMMO,
        (3, PickupKind::Fuel) => ACT3_LOOT_FUEL,
        (3, PickupKind::Medical) => ACT3_LOOT_MEDICAL,
        (3, PickupKind::Cigarettes) => ACT3_LOOT_CIGARETTES,
        _ => &[],
    }
}

