// 6x-ish Dienstglas framing. The old 4° field was effectively a 17-18x screen-space zoom from the
// normal commander/on-foot views: powerful enough to amplify every distant render artifact and too
// tight to scan with. Ten degrees keeps the binoculars stronger than the 5x TZF stop while retaining
// enough context to search the horizon.
const BINOCULAR_FOV_DEG: f32 = 10.0;
const BINOCULAR_RAISE_S: f32 = 0.45;
const BINOCULAR_LOWER_S: f32 = 0.32;
/// The optical picture must not switch on while the housing is still crossing the viewer's face.
/// At this point the real prop has reached the eyes; the near-plane is inside the eyecups and the
/// existing double-eyepiece mask becomes the view through the instrument.
const BINOCULAR_OPTICAL_CONTACT: f32 = 0.94;
const BINOCULAR_PROP_PATH: &str = "assets/flavor/Characters/german-panzertruppe-adrielcz-cc-by-4/baked/german_field_binoculars_physical.glb";
const ENIGMA_PROP_PATH: &str =
    "assets/flavor/Props/enigma-machine-ashish0096-cc-by-4/baked/enigma_machine_runtime.glb";

fn load_required_reviewed_prop(path: &str, label: &str) -> anyhow::Result<CpuMesh> {
    crate::gltf_load::load_glb(path)
        .with_context(|| format!("load required reviewed {label} runtime GLB at {path}"))
}

/// Hull-local base of the physical Enigma at the radio/bow-MG station. The authored machine faces
/// local +Z; the quarter-turn aims its keyboard inward (+X), directly toward the radio operator.
/// Its 0.544 m height then occupies y=0.74..1.284 m, beneath that post's 1.58 m eye line.
const ENIGMA_RADIO_BASE: Vec3 = Vec3::new(-1.20, 0.74, 1.22);

fn advance_binocular_raise(current: f32, requested: bool, dt: f32) -> f32 {
    let dt = dt.max(0.0);
    if requested {
        (current + dt / BINOCULAR_RAISE_S).min(1.0)
    } else {
        (current - dt / BINOCULAR_LOWER_S).max(0.0)
    }
}

fn binocular_optics_ready(raise: f32) -> bool {
    raise >= BINOCULAR_OPTICAL_CONTACT
}

fn couch_view_binocular_raise(
    viewer_role: Option<crate::lan::LanRole>,
    commander_raise: f32,
) -> f32 {
    if viewer_role == Some(crate::lan::LanRole::Commander) {
        commander_raise
    } else {
        0.0
    }
}

fn enigma_radio_model(hull_model: Mat4) -> Mat4 {
    hull_model
        * Mat4::from_translation(ENIGMA_RADIO_BASE)
        * Mat4::from_rotation_y(std::f32::consts::FRAC_PI_2)
}

/// Camera-local transform for the actual field-glasses mesh during the hand-to-eye travel. There
/// is deliberately no unregistered first-person arm stand-in. At optical contact the camera is at
/// the eyecups and this foreground housing is near-plane clipped/hidden under the eyepiece view.
fn binocular_prop_model(camera: &crate::camera::Camera, raise: f32) -> Option<Mat4> {
    if raise <= 0.01 || binocular_optics_ready(raise) {
        return None;
    }
    let t = smoothstep(0.0, BINOCULAR_OPTICAL_CONTACT, raise);
    let forward = camera.forward();
    let screen_right = forward.cross(Vec3::Y).normalize_or_zero();
    let up = screen_right.cross(forward).normalize_or_zero();
    let model_right = up.cross(forward).normalize_or_zero();
    if screen_right.length_squared() <= 1.0e-6
        || up.length_squared() <= 1.0e-6
        || model_right.length_squared() <= 1.0e-6
    {
        return None;
    }

    // The actual baked instrument's eyecups are at +Y; its viewing axis is -Y. Rotate the
    // measured source axis toward the eyes during the existing lift instead of carrying two
    // upward-facing tubes all the way into the camera. No source geometry is changed.
    const EYECUP_MIDPOINT: Vec3 = Vec3::new(0.0, 0.136_484_95, -0.000_534_385);
    const EYE_RELIEF_M: f32 = 0.015;
    let camera_basis = Mat4::from_cols(
        model_right.extend(0.0),
        up.extend(0.0),
        forward.extend(0.0),
        Vec3::ZERO.extend(1.0),
    );
    let contact_rotation = Mat4::from_rotation_x(-std::f32::consts::FRAC_PI_2);
    let rest = camera.pos + forward * 0.34 + screen_right * 0.15 - up * 0.31;
    let contact = camera.pos + forward * EYE_RELIEF_M
        - (camera_basis * contact_rotation).transform_vector3(EYECUP_MIDPOINT);
    let rotation = Mat4::from_rotation_z(-0.18 * (1.0 - t))
        * Mat4::from_rotation_x(-0.35 + (-std::f32::consts::FRAC_PI_2 + 0.35) * t);
    Some(Mat4::from_translation(rest.lerp(contact, t)) * camera_basis * rotation)
}

// ── Coaxial + hull MG34 (rapid automatic fire) ──────────────────────────────────────────────────
// The two MG34s: the coaxial (fired down the gunner's sight, on the main-gun axis) and the hull/bow
// gun (the radio-operator's forward MG). RAPID automatic fire paced by a firing-rate timer so rounds
// aren't spawned one-per-frame. MGs are USELESS against armour — they only clatter + spark off a
// T-34; they are lethal to persistent SOFT targets (see `mg_hit`).
const MG_FIRE_INTERVAL: f32 = 0.075; // s between rounds — ~13 rounds/sec (MG34 cyclic-rate feel)
const MG_TRACER_EVERY: u32 = 2; // every Nth round is a visible tracer (classic tracer stream)
const MG_TRACER_SPEED: f32 = 700.0; // m/s — thin, fast streaks (vs the 450 m/s cannon shell)
const MG_RANGE: f32 = 900.0; // m — maximum simulated MG flight
const MG_DISP: f32 = 0.010; // fire-cone dispersion (MGs spray, they don't lay a precise bolt)
const MG_FLASH_DUR: f32 = 0.065; // s — muzzle-flash persistence (≈ the fire interval, so it reads
                                 // as a near-continuous strobing flash while firing, not stutter)
const N_MG_TRACER: usize = 8; // pooled MG tracer streaks (coax + hull share; one MG at a time)
const N_MG_IMPACT: usize = 8; // pooled MG impact spurts (armour sparks / snow-dirt kicks)
const MG_SOUND_EVERY: u32 = 4; // only every Nth round plays an impact sound (don't flood sinks)
const MG_HEAT_PER_SEC: f32 = 0.28; // barrel heat gained per second of sustained fire (→ ~3.5 s to cook)
const MG_COOL_PER_SEC: f32 = 0.45; // heat shed per second when not firing
const MG_COOL_RESUME: f32 = 0.35; // once overheated, must cool below this before it fires again
const VOL_MG_GRAVEL: f32 = 0.55; // rounds clattering off a T-34's armour — light, not a cannon CLANG
const VOL_MG_GROUND: f32 = 0.40; // rounds spitting up snow/dirt on the terrain

// ── Speed of sound: distant combat is SEEN, then HEARD a beat later ─────────────────────────────
// Every combat sound whose SOURCE is away from the player (enemy gunfire, kill/turret/cook-off
// explosions, impacts) is queued and released only once its wavefront reaches the player: delay =
// range / 343 m/s, volume attenuated by range. The player's OWN main gun bypasses this (instant —
// you're right there). Ambient horizon explosions ride the same queue at long delay + low volume.
const SPEED_OF_SOUND: f32 = crate::pressure_front::SPEED_OF_SOUND_M_S; // m/s
const SOUND_REF_DIST: f32 = 180.0; // m — volume falls off as ref/(ref+range); ~half at this range
                                   // Combat SFX base volumes (before range attenuation). Nudged above unity so incoming/outgoing fire
                                   // reads CLEARLY against the deliberately near-silent engine+wind mix (the CLANGs and cracks are the
                                   // point). Close sources (enemy rounds landing on the Tiger) stay ~full; distant ones fall off.
const VOL_ENEMY_GUN: f32 = 1.2;
const VOL_IMPACT_TANK: f32 = 1.15;
const VOL_IMPACT_GROUND: f32 = 0.9;
const VOL_CLANG: f32 = 1.25; // the CLANG of a bounce should ring out clearly
const VOL_NEAR_MISS: f32 = 1.25; // the supersonic crack of a round snapping past
const VOL_PENETRATION: f32 = 1.2;
/// A strike on the player's own armor, on the impact bus. The synthesized hit already carries its
/// energy/proximity loudness law; this anchors the heaviest close strikes at the impact ceiling.
const VOL_HIT_ON_PLAYER: f32 = 2.2;
const VOL_KILL: f32 = 1.5; // big kill / turret-pop / cook-off booms carry across the field
const VOL_AMBIENT_EXP: f32 = 1.5; // distant battlefield boom base — heavily range-attenuated
                                  // Ambient battlefield explosions: a faint, delayed boom out on the horizon around the player at
                                  // randomized intervals, so the whole front reads as a battle in progress (not just this duel).
const AMBIENT_EXP_MIN: f32 = 6.0; // s — shortest gap between distant explosions
const AMBIENT_EXP_MAX: f32 = 20.0; // s — longest gap (the spread keeps the front feeling alive)
const AMBIENT_DIST_MIN: f32 = 380.0; // m — distant, out on the horizon
const AMBIENT_DIST_MAX: f32 = 850.0;

// ── Kill-payoff / wreck model ─────────────────────────────────────────────────────────────────
// Destroying a T-34 is the whole point of the fight, so it has to LAND. Every kill leaves a
// persistent BURNING WRECK (physical flame/soot grains + a rising smoke column); a chunk of kills go
// CATASTROPHIC — the ammunition detonates, the turret is blown clean off and tumbles away; the rest
// just burn, and some of those cook off their stowed ammunition seconds later with a delayed WHUMP.
const CATASTROPHIC_CHANCE: f32 = 0.35; // fraction of kills that pop the turret (ammo-rack detonation)
const COOKOFF_CHANCE: f32 = 0.55; // of the *burning* (non-pop) wrecks, fraction that later cook off
const COOKOFF_MIN: f32 = 3.0; // s — earliest a burning wreck cooks off
const COOKOFF_MAX: f32 = 8.0; // s — latest
const TURRET_POP_V0_MIN: f32 = 14.0; // m/s — turret launch (vertical) velocity, ammo-rack blast
const TURRET_POP_V0_MAX: f32 = 20.0;
const N_BLAST: usize = 4; // pooled big emissive fireball FX (kills / pops / cook-offs overlap)
const N_DEBRIS: usize = 48; // pooled fragments: a penetration fills the compartment with sparks

/// How a destroyed enemy reads as a wreck.
#[derive(Copy, Clone, PartialEq, Eq, Default)]
enum WreckKind {
    #[default]
    None, // still alive — not a wreck
    Burn,      // hull + turret stay, engulfed in flame (may cook off later)
    TurretPop, // CATASTROPHIC — the turret was blown off and is tumbling ballistically
}

/// Per-enemy wreck state, held in a `Vec<Wreck>` parallel to `Game::enemies`. Inert until that
/// enemy is destroyed (`kind == None`). Drives the persistent fire, the tumbling turret-pop
/// physics, and the delayed cook-off.
#[derive(Clone, Default)]
struct Wreck {
    kind: WreckKind,
    burning: bool,
    fire_t: f32, // seconds since the wreck was created (fire flicker + smoke clock)
    // ── turret-pop ballistics (the turret mesh flies off) ──
    t_pos: Vec3, // world position of the tumbling turret ring
    t_vel: Vec3, // integrated under gravity
    t_spin_axis: Vec3,
    t_spin_rate: f32,  // rad/s
    t_ang: f32,        // accumulated tumble angle
    t_base_rot: Quat,  // the turret's world orientation at the instant it popped
    t_gun_local: Mat4, // gun transform relative to the turret (so the barrel flies with it)
    t_rest_y: f32,     // world Y the turret comes to rest at
    landed: bool,
    // ── delayed cook-off ──
    cookoff_t: Option<f32>, // countdown to the secondary; None = never cooks off (or already did)
    cooked: bool,
    cook_flash: f32, // brief fire-intensity spike right after a cook-off, decays to 0
}

impl Wreck {
    /// World transform for the tumbling turret mesh.
    fn turret_pop_xf(&self) -> Mat4 {
        let spin = Quat::from_axis_angle(self.t_spin_axis, self.t_ang);
        Mat4::from_rotation_translation(spin * self.t_base_rot, self.t_pos)
    }
    /// World transform for the gun mesh, rigidly attached to the tumbling turret.
    fn gun_pop_xf(&self) -> Mat4 {
        self.turret_pop_xf() * self.t_gun_local
    }
}

/// One pooled big emissive fireball (kill / turret-pop / cook-off blast).
#[derive(Clone, Default)]
struct Blast {
    t: f32,   // life remaining
    dur: f32, // total life
    pos: Vec3,
    scale: f32, // peak radius
    hot: f32,   // peak emissive intensity
}

/// One pooled snow/dust near-miss puff: a quick white-grey burst that expands where an incoming
/// round buried itself in the snow beside the player. It is ordinary particulate material, never
/// an emitter.
#[derive(Clone, Default)]
struct SnowPuff {
    t: f32,   // life remaining
    dur: f32, // total life
    pos: Vec3,
    scale: f32, // peak radius (closer near-miss = bigger)
}

/// One pooled MG tracer streak: the thin/fast MG round, animated with the same muzzle→impact lerp
/// as the cannon tracer but small + rapid. Coax and hull share the pool (only one MG fires at once).
#[derive(Clone, Default)]
struct MgTracer {
    active: bool,
    t: f32,
    dur: f32,
    from: Vec3,
    to: Vec3,
    dir: Vec3,
}

/// One pooled MG impact spurt: a quick burst where a round terminates. `tank` = sparks off armour
/// (hot, small, bright); otherwise a snow/dirt kick (softer, larger). Own-colour warm-white so the
/// snow reads as kicked-up powder, not fire (the armour sparks blow white-hot through bloom).
#[derive(Clone, Default)]
struct MgImpact {
    t: f32,
    dur: f32,
    pos: Vec3,
    tank: bool,
}

/// One low-velocity, fin-stabilized Panzerfaust bomb in flight.
#[derive(Clone, Default)]
struct PanzerfaustShot {
    active: bool,
    id: u64,
    origin: Vec3,
    age: f32,
    pos: Vec3,
    vel: Vec3,
    distance: f32,
}

const PANZERFAUST_ARMING_DISTANCE: f32 = 5.0;

fn clamp_panzerfaust_segment(old_distance: f32, proposed_len: f32) -> (f32, bool) {
    let proposed_len = proposed_len.max(0.0);
    let remaining = (crate::foot::PANZERFAUST_MAX_RANGE - old_distance).max(0.0);
    (proposed_len.min(remaining), proposed_len >= remaining)
}

fn panzerfaust_contact_distance(old_distance: f32, contact_t: f32) -> f32 {
    old_distance + contact_t
}

/// Dedicated first-person P08 casing; the Tiger casing pool is metre-scale 8.8 cm brass.
#[derive(Clone, Default)]
struct LugerCasing {
    active: bool,
    pos: Vec3,
    vel: Vec3,
    axis: Vec3,
    angle: f32,
    t: f32,
}

/// One pooled spark/debris chunk flung from a blast, falling under gravity.
#[derive(Clone, Default)]
struct Spark {
    t: f32, // life remaining
    dur: f32,
    pos: Vec3,
    vel: Vec3,
    size: f32,
    hot: bool,    // blast metal glows; broken masonry stays ordinary lit material
    streak: bool, // spall is a thin velocity-aligned spark, not an isotropic debris chunk
}

/// Deterministic pseudo-random in [0,1) from a counter (no rand crate — matches the enemy-AI
/// dispersion jitter elsewhere in this file).
fn hash01(n: u32) -> f32 {
    ((n.wrapping_mul(2654435761) >> 8) & 0xffff) as f32 / 65536.0
}

/// Near-miss snow-puff decision from a round's closest-approach horizontal distance to the player:
/// `Some(close)` with close in (0,1] (1 right on the hull, →0 at the radius) when the round snapped
/// within `NEAR_MISS_PUFF_RADIUS`, `None` (no puff — the round passed too wide) otherwise. `close`
/// scales the puff size + sound (closer = bigger/louder). Pure so the radius + scaling is
/// unit-testable without a GPU.
fn near_miss_puff_scale(horiz: f32) -> Option<f32> {
    if horiz <= NEAR_MISS_PUFF_RADIUS {
        Some(1.0 - (horiz / NEAR_MISS_PUFF_RADIUS).clamp(0.0, 1.0))
    } else {
        None
    }
}

/// GLSL-style smoothstep for FX envelopes.
fn smoothstep(e0: f32, e1: f32, x: f32) -> f32 {
    let t = ((x - e0) / (e1 - e0)).clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

// ── Engine-native destructibility: shells knock down the ruined city's walls/facades ─────────────
// A subset of the tall standing structures — the near city walls/facades + the free-standing cover
// walls — are DESTRUCTIBLE. The scene is FIXED at `Game::build` (no mesh can be added at runtime), so
// each destructible pre-allocates BOTH its intact mesh AND a hidden low-rubble heap at the same
// footprint (see `city::rubble_heap`); a main-gun round that strikes one chips its HP and, at 0 HP,
// COLLAPSES it — the intact is hidden, the rubble revealed, a debris + masonry-dust burst is flung
// from the pooled FX, a heavy collapse boom scheduled, and the piece's LOS occluder DOWNGRADED to
// knee height so a felled wall stops concealing a Tiger. HP scales with size so a big HE/AP round
// drops a small wall in one hit and a large facade in ~three. Deterministic (hash01, no rand).
const STRUCT_SHELL_DAMAGE: f32 = 55.0; // one main-gun HE/AP round vs masonry
const STRUCT_HP_MIN: f32 = 50.0; // smallest wall — one shell drops it
const STRUCT_HP_MAX: f32 = 155.0; // largest facade — ~three shells
const STRUCT_MAX_DESTRUCTIBLES: usize = 44; // hard cap — keep the set a few dozen, cheap
const CITY_DESTRUCT_CAP: usize = 18; // of those, at most this many near-front city wall pieces
const COLLAPSE_OCCLUDER_H: f32 = 0.6; // m — occluder top after collapse (below the tank sightline)
const MODULAR_COLLAPSE_FX_BUDGET: usize = 1; // one beat per propagated compiler delta
const MASONRY_DEBRIS_COUNT: usize = 6; // safely below the shared 12-slot pool
const MASONRY_DUST_PUFFS: usize = 2;

fn take_collapse_fx_budget(remaining: &mut usize) -> bool {
    if *remaining == 0 {
        false
    } else {
        *remaining -= 1;
        true
    }
}

fn structure_fx_origin(piece_center: Vec3, modular_ground_y: Option<f32>) -> Vec3 {
    modular_ground_y.map_or(piece_center, |ground_y| {
        Vec3::new(piece_center.x, ground_y + 0.20, piece_center.z)
    })
}

fn debris_emissive(hot: bool, life_fraction: f32) -> f32 {
    if hot {
        3.0 + 8.0 * life_fraction.clamp(0.0, 1.0)
    } else {
        0.0
    }
}

/// Terrain relief under a building footprint above which the build reports an unflattened pad.
const PAD_RELIEF_REPORT_M: f32 = 0.3;

/// Lowest and highest terrain height sampled on a 1 m grid over a placement's footprint.
fn footprint_terrain_range(
    hf: &Heightfield,
    placement: &crate::building_placement::BuildingPlacement,
) -> (f32, f32) {
    let (min, max) = placement.footprint_xz();
    let steps_x = ((max.x - min.x).ceil() as usize).max(1);
    let steps_z = ((max.y - min.y).ceil() as usize).max(1);
    let mut range = (f32::INFINITY, f32::NEG_INFINITY);
    for i in 0..=steps_x {
        for j in 0..=steps_z {
            let x = min.x + (max.x - min.x) * i as f32 / steps_x as f32;
            let z = min.y + (max.y - min.y) * j as f32 / steps_z as f32;
            let h = hf.height_at(x, z);
            range = (range.0.min(h), range.1.max(h));
        }
    }
    range
}


/// One destructible standing structure (a near city wall/facade or a free-standing cover wall). The
/// scene is fixed at build time, so BOTH the intact mesh and a hidden collapsed-rubble heap at the
/// same footprint are pre-allocated up front; destruction just flips their visibility, bursts debris,
/// and downgrades the LOS occluder. All-`Copy` so `collapse_structure` can lift a snapshot out of the
/// `Vec` before mutating the rest of `Game`.
#[derive(Clone, Copy)]
struct Destructible {
    /// The standing mesh (hidden on collapse): a loose scene slot, or a compiled building module's
    /// instance of its shared kit prototype.
    intact: crate::renderer::SceneRef,
    /// The pre-allocated collapsed heap (revealed on collapse): a loose slot, or the module's
    /// grounded rubble instance (shared by every proxy of that module).
    rubble: crate::renderer::SceneRef,
    occ: usize,    // index into `Game::occluders` — downgraded to knee height on collapse
    min: Vec3,     // world AABB of the intact piece (the shell-impact hit test)
    max: Vec3,
    hp: f32,
    max_hp: f32,
    alive: bool,
    seed: u32,       // deterministic debris/dust spread
    class: Material, // material class — drives the crush gate (and, later, shell response)
}

impl Destructible {
    fn center(&self) -> Vec3 {
        (self.min + self.max) * 0.5
    }
    /// Apply `dmg`; returns true if this hit dropped the piece to rubble (0 HP). A felled piece takes
    /// no further damage. Pure — the FX/occluder consequences live in `collapse_structure`.
    fn hit(&mut self, dmg: f32) -> bool {
        if !self.alive {
            return false;
        }
        self.hp -= dmg;
        if self.hp <= 0.0 {
            self.hp = 0.0;
            self.alive = false;
            true
        } else {
            false
        }
    }
}

/// Scratch record for a destructible collected during scene assembly, before its paired rubble heap
/// is pre-allocated (see `Game::build`). Promoted to a `Destructible` once the rubble slot is known.
struct DestructibleBuild {
    intact: usize,
    occ: usize,
    min: Vec3,
    max: Vec3,
    hp: f32,
    seed: u32,
    class: Material,
    /// (building instance, compiler placement) of a building module; legacy loose walls are `None`.
    building_module: Option<(usize, usize)>,
}

/// HP for a destructible scaled by its footprint: a small wall segment drops in one shell, a large
/// facade takes ~three. `max_dim` = the piece's largest world extent. Pure so it's unit-testable.
fn structure_hp(max_dim: f32) -> f32 {
    let size01 = ((max_dim - 3.0) / 6.0).clamp(0.0, 1.0); // ~3 m wall → 0, ~9 m facade → 1
    STRUCT_HP_MIN + (STRUCT_HP_MAX - STRUCT_HP_MIN) * size01
}

/// The LOS occluder a wall leaves behind once it collapses: the top is dropped to knee height so the
/// felled wall no longer breaks a tank-centre sightline (matches the "can't hide behind a knee-high
/// brick pile" rule the intact occluders already rely on). Pure so the downgrade is unit-testable.
fn collapsed_occluder(o: stealth::Occluder) -> stealth::Occluder {
    stealth::Occluder {
        min: o.min,
        max: Vec3::new(o.max.x, o.min.y + COLLAPSE_OCCLUDER_H, o.max.z),
    }
}

/// The LOS occluder a failed record leaves, on the ground its rubble lies on. A legacy wall's heap
/// lies where the wall stood (`collapsed_occluder`). A building module's rubble lies on its
/// building's ground under the module's footprint (`building_render::grounded_transform`), so its
/// knee-high occluder stands there too: before 2026-09-29 a module that fell from an upper storey
/// left its 0.6 m blocker floating at that storey, over nothing visible (11,384 of the 12,562
/// failed-module boxes of the urban-intro district at build stood more than 3 m up, the highest
/// 20 m). `WorldIndex` indexes a building module's occluder down to its building's ground, so the
/// indexed box keeps holding the live one.
fn collapsed_occluder_on(o: stealth::Occluder, ground_y: Option<f32>) -> stealth::Occluder {
    match ground_y {
        None => collapsed_occluder(o),
        Some(ground_y) => stealth::Occluder {
            min: Vec3::new(o.min.x, ground_y, o.min.z),
            max: Vec3::new(o.max.x, ground_y + COLLAPSE_OCCLUDER_H, o.max.z),
        },
    }
}

// ── Material classes + TRACK CRUSH (docs/DESTRUCTION.md §2/§4, slice 1) ──────────────────────────
// Every destructible carries a material class that answers how it responds to being DRIVEN INTO.
// Crush is a momentum gate: the 57-tonne Tiger (crush power 3) grinds through brick, crawls through
// stone, and is stopped dead by bunker concrete; a lighter vehicle treats every tier one step
// harder (enemies aren't wired to crush yet — see §7 of the doc). The signature moment is the
// GRIND: speed clamps against the wall while crush damage flows into the same HP pool the gun
// uses, then the piece collapses through the same `collapse_structure` path and the tank surges
// over the fresh rubble. Shell-side properties (ap_cost/deflection) land with the pen-ray slice.
/// Timber/Stone/Bunker have no act-1 spawners yet (huts and bunkers are act-2/3 world classes) —
/// they're in the table now so the crush gate and its tests cover the full tier ladder.
#[allow(dead_code)]
#[derive(Clone, Copy, PartialEq, Debug)]
enum Material {
    Timber, // izba walls, barns, plank barricades — bursts on contact at speed
    Brick,  // the ruined city's walls/facades (every act-1 destructible today)
    Stone,  // heavy masonry — a Tiger-only crawl-grind
    Bunker, // poured concrete — never crushes, never collapses
}

/// How a material meets a crush-power-3 vehicle (the Tiger).
/// `tier`: 1 bursts at speed / 2 the grind / 3 crawl-grind / 4 hard stop.
/// `vmax`: speed cap (m/s) while pressed against the piece. `dps`: crush damage per second.
#[derive(Clone, Copy)]
struct CrushSpec {
    tier: u8,
    vmax: f32,
    dps: f32,
}

impl Material {
    fn crush(self) -> CrushSpec {
        match self {
            Material::Timber => CrushSpec {
                tier: 1,
                vmax: 7.0,
                dps: 400.0,
            },
            Material::Brick => CrushSpec {
                tier: 2,
                vmax: 3.5,
                dps: 65.0,
            },
            Material::Stone => CrushSpec {
                tier: 3,
                vmax: 1.3,
                dps: 30.0,
            },
            Material::Bunker => CrushSpec {
                tier: 4,
                vmax: 0.0,
                dps: 0.0,
            },
        }
    }
}

/// Deterministic 8.8 cm KwK 36 round, already authored at real scale along +Z. Dark grey is PzGr
/// (AP), yellow is SprGr (HE); both retain a brass case and the same gameplay silhouette.
fn round_88_mesh(he: bool) -> crate::gltf_load::CpuMesh {
    if he {
        crate::procedural_ordnance::he_round_mesh()
    } else {
        crate::procedural_ordnance::ap_round_mesh()
    }
}

/// Deterministic open-mouth spent case, centred at the origin with its long axis along +Z.
fn spent_88_case_mesh() -> crate::gltf_load::CpuMesh {
    crate::procedural_ordnance::spent_case_mesh()
}

/// Re-author an X-forward held prop as a centred +Z-forward runtime mesh of `length_m`.
fn normalize_centered_x_to_z(
    m: crate::gltf_load::CpuMesh,
    length_m: f32,
) -> crate::gltf_load::CpuMesh {
    let scale = length_m / (m.max.x - m.min.x).max(1e-3);
    let center = (m.min + m.max) * 0.5;
    m.transformed(
        Mat4::from_scale(Vec3::splat(scale))
            * Mat4::from_rotation_y(-std::f32::consts::FRAC_PI_2)
            * Mat4::from_translation(-center),
    )
}

/// Preserve an authored upright prop's +Y axis while centring it and assigning an exact length.
fn normalize_centered_y(m: crate::gltf_load::CpuMesh, length_m: f32) -> crate::gltf_load::CpuMesh {
    let scale = length_m / (m.max.y - m.min.y).max(1e-3);
    let center = (m.min + m.max) * 0.5;
    m.transformed(Mat4::from_scale(Vec3::splat(scale)) * Mat4::from_translation(-center))
}

fn luger_reload_prop_count(mag: u32, reserve: u32) -> usize {
    crate::foot::MAG_CAP.saturating_sub(mag).min(reserve).min(3) as usize
}

/// Ground an upright Y-axis prop at the origin, centre it laterally, and give it an exact height.
fn normalize_bottom_centered_y(
    m: crate::gltf_load::CpuMesh,
    height_m: f32,
) -> crate::gltf_load::CpuMesh {
    let scale = height_m / (m.max.y - m.min.y).max(1e-3);
    let bottom_center = Vec3::new(
        (m.min.x + m.max.x) * 0.5,
        m.min.y,
        (m.min.z + m.max.z) * 0.5,
    );
    m.transformed(Mat4::from_scale(Vec3::splat(scale)) * Mat4::from_translation(-bottom_center))
}

const EXTINGUISHER_ASSET: &str = "assets/flavor/psx-fire-extinguisher/extinguisher.glb";
// Upper valve outlet in the bottom-centred source model. The original valve spans source
// y=1.140625..1.256506; this anchor is just beyond its forward face, above the cylinder.
// The old y=0.55 anchor incorrectly sprayed through the middle of the bottle.
const EXTINGUISHER_OUTLET: Vec3 = Vec3::new(0.0, 1.244_999_8, -0.025_891_4);

/// Preserve the original extinguisher's hose, lever, label and texture. The previously substituted
/// gas cylinder had no extinguisher mechanism; recoloring it red could not restore that silhouette.
fn load_extinguisher_mesh() -> anyhow::Result<crate::gltf_load::CpuMesh> {
    Ok(normalize_bottom_centered_y(crate::gltf_load::load_glb(EXTINGUISHER_ASSET)?, 1.348_838))
}

fn brass_albedo(mut m: crate::gltf_load::CpuMesh) -> crate::gltf_load::CpuMesh {
    if let Some(texture) = m.texture.as_mut() {
        for pixel in texture.rgba_mut().chunks_exact_mut(4) {
            let luminance =
                0.299 * pixel[0] as f32 + 0.587 * pixel[1] as f32 + 0.114 * pixel[2] as f32;
            pixel[0] = (72.0 + luminance * 1.45).min(230.0) as u8;
            pixel[1] = (48.0 + luminance * 0.92).min(178.0) as u8;
            pixel[2] = (16.0 + luminance * 0.30).min(82.0) as u8;
        }
    }
    m
}

/// Scale a mesh's base-color texture RGB by `f` (clamped). Used for small, dark-authored interactive
/// Tiger parts that must remain legible in the cold interior grade without becoming emissive.
fn brighten_albedo(mut m: crate::gltf_load::CpuMesh, f: f32) -> crate::gltf_load::CpuMesh {
    if let Some(t) = m.texture.as_mut() {
        for px in t.rgba_mut().chunks_exact_mut(4) {
            for c in &mut px[..3] {
                *c = ((*c as f32) * f).min(255.0) as u8;
            }
        }
    }
    m
}

/// Three compact spare track shoes strapped across an armor breach. This is a cheap, readable field
/// expedient: one rigid procedural mesh, no new texture/asset, and still one ArmorScar record. The
/// local XY plane lies against the plate and +Z points out from it.
fn armor_track_patch_mesh() -> CpuMesh {
    let steel = [128, 122, 104]; // worn bare edges must read against a shadowed Tiger flank
    let mut parts = Vec::with_capacity(6);
    for y in [-0.38f32, 0.0, 0.38] {
        parts.push(box_mesh(
            Vec3::new(-1.0, y - 0.15, -0.50),
            Vec3::new(1.0, y + 0.15, 0.50),
            steel,
        ));
        // Guide tooth: a small central lug makes the silhouette read as track, not sheet steel.
        parts.push(box_mesh(
            Vec3::new(-0.13, y - 0.09, 0.42),
            Vec3::new(0.13, y + 0.09, 1.0),
            steel,
        ));
    }
    let mut parts = parts.into_iter();
    let mut out = parts.next().expect("track patch has parts");
    for part in parts {
        let base = out.vertices.len() as u32;
        out.vertices.extend(part.vertices);
        out.indices
            .extend(part.indices.into_iter().map(|index| base + index));
        out.min = out.min.min(part.min);
        out.max = out.max.max(part.max);
    }
    out
}

/// Point + direction at `dist` along a piecewise tracer route (transit holes need the exact
/// spot/heading the round punched through at).
fn route_at(route: &[Vec3], dist: f32) -> (Vec3, Vec3) {
    let mut remaining = dist;
    for w in route.windows(2) {
        let len = w[0].distance(w[1]);
        if remaining <= len || len <= 1e-6 {
            let dir = (w[1] - w[0]) / len.max(1e-6);
            return (w[0] + dir * remaining.min(len), dir);
        }
        remaining -= len;
    }
    let last = *route.last().unwrap_or(&Vec3::ZERO);
    let dir = if route.len() >= 2 {
        (last - route[route.len() - 2]).normalize_or_zero()
    } else {
        Vec3::Z
    };
    (last, dir)
}

/// The compartment frame a physical blood droplet/stain rides in. Bow crew are fixed to the hull;
/// turret crew and every fighting-compartment surface rotate with the turret. Keeping the physics in
/// that local frame means settled evidence never slides through the vehicle while it drives.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum BloodFrame {
    #[default]
    Hull,
    Turret,
}

/// One independently simulated chip of hot armour or penetrator steel. This is the sole terminal-
/// ballistics body: its stable ID, swept path and contacts drive crew/module damage, the visible
/// cube, its history-derived trail and every ricochet/near-miss sound. There is no parallel visual
/// spark or analytically resampled damage cone.
#[derive(Clone, Copy, Debug, Default)]
struct HotFragment {
    id: u64,
    penetration_id: u64,
    active: bool,
    settled: bool,
    /// Exact armor-side origin and last rendered simulation position in `frame` coordinates.
    /// Trails span only this body's measured position history; they never invent a beam path.
    origin: Vec3,
    prev_pos: Vec3,
    /// Armor contacts can lie outside the smaller playable cabin collision proxies. A fragment is
    /// allowed to cross that truthful dead space and starts bouncing only after entering the cabin.
    entered_compartment: bool,
    /// Set only after this chip supplies one real listener near-miss, preventing a slow multi-frame
    /// pass or later bounces from replaying the same whizz.
    audio_whizzed: bool,
    frame: BloodFrame,
    pos: Vec3,
    vel: Vec3,
    size: f32,
    ang: Vec3,
    spin: Vec3,
    age: f32,
    life: f32,
    bounces: u8,
    seed: u32,
}

/// One real cube-to-cabin contact from the latest simulation frame. Audio consumes this bounded,
/// deterministic sample to place individual ticks around the listener; `turret_local` identifies
/// which moving compartment frame owns `local_pos`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HotFragmentCollision {
    pub turret_local: bool,
    pub local_pos: Vec3,
    pub speed: f32,
    pub seed: u32,
    pub bounce_count: u8,
}

/// Ballistic families used only to size the physical fragment population. They are derived solely
/// from the resolved shell/plate event, never from downstream casualties or module outcomes.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
enum FragmentShowerKind {
    #[default]
    Deflection,
    CleanKinetic,
    SpallHeavy,
    Explosive,
    Catastrophic,
}

/// Physical initial-condition profile for the one authoritative fragment population.
#[derive(Clone, Copy, Debug, PartialEq)]
struct FragmentShowerProfile {
    kind: FragmentShowerKind,
    fragment_count: usize,
    speed_min: f32,
    speed_max: f32,
    fragment_life: f32,
    cone_half_tan: f32,
    min_size_m: f32,
    max_size_m: f32,
}

/// One RTT periscope screen (from tiger_rtt_screens.json): an eyepiece face set whose atlas
/// tile shows what its aperture sees. `frame`: 0 hull / 1 turret / 2 gun.
struct RttScreen {
    frame: usize,
    centroid: Vec3,
    bearing: Vec3,
    tile: u32,
}

/// A periscope tile is a complete offscreen scene render, not a cheap material update. Updating
/// the whole eleven-pane ring every simulation frame multiplied terrain, shadow, bloom, snow and
/// draw submission cost by eleven before the player's actual view was rendered. Keep every pane
/// live with a rolling cadence instead; an override remains useful for capture rigs and profiling.
fn parse_rtt_update_budget(value: Option<&str>, screen_count: usize) -> Option<usize> {
    if screen_count == 0 {
        return Some(0);
    }
    match value.map(str::trim) {
        Some(value) if matches!(value.to_ascii_lowercase().as_str(), "all" | "full") => {
            Some(screen_count)
        }
        Some(value) => value
            .parse::<usize>()
            .ok()
            .filter(|requested| *requested > 0)
            .map(|requested| requested.min(screen_count)),
        None => Some(1),
    }
}

fn rtt_updates_per_frame(screen_count: usize) -> usize {
    let configured = std::env::var("KESSEL_RTT_UPDATES_PER_FRAME").ok();
    parse_rtt_update_budget(configured.as_deref(), screen_count).unwrap_or_else(|| {
        println!(
            "[panzerrechnersystem] ignoring invalid KESSEL_RTT_UPDATES_PER_FRAME={:?}; using 1",
            configured.as_deref().unwrap_or_default(),
        );
        usize::from(screen_count > 0)
    })
}

/// `(first tile, number of tiles, next cursor)` for a bounded circular refresh. Keeping this pure
/// makes the zero-screen and wrap behavior explicit instead of relying on modulo side effects.
fn rtt_refresh_plan(
    cursor: usize,
    screen_count: usize,
    requested_updates: usize,
) -> (usize, usize, usize) {
    if screen_count == 0 {
        return (0, 0, 0);
    }
    let first = cursor % screen_count;
    let updates = requested_updates.clamp(1, screen_count);
    let next = (first + updates) % screen_count;
    (first, updates, next)
}

/// Budget-one live scheduler: most frames refresh the pane nearest the viewer's current gaze, but
/// every eighth frame pays down the stalest background pane so the rest of the ring never freezes.
/// Alignment values are camera-forward dot products; ties are stable by pane index.
fn rtt_priority_pick(alignments: &[f32], last_refresh: &[u64], tick: u64) -> Option<usize> {
    if alignments.is_empty() || alignments.len() != last_refresh.len() {
        return None;
    }
    const BACKGROUND_INTERVAL: u64 = 8;
    if tick % BACKGROUND_INTERVAL == BACKGROUND_INTERVAL - 1 {
        return last_refresh
            .iter()
            .enumerate()
            .min_by_key(|&(index, &last)| (last, index))
            .map(|(index, _)| index);
    }
    alignments
        .iter()
        .enumerate()
        .max_by(|(a_index, a), (b_index, b)| a.total_cmp(b).then_with(|| b_index.cmp(a_index)))
        .map(|(index, _)| index)
}

/// High-end couch scheduler: keep the best pane for every occupied crew camera current, then spend
/// one slot on the stalest remaining pane so no part of the ring freezes. Duplicate best panes are
/// collapsed in stable role order, and all ties remain stable by pane index.
fn rtt_couch_union_pick(view_alignments: &[Vec<f32>], last_refresh: &[u64]) -> Vec<usize> {
    if last_refresh.is_empty()
        || view_alignments
            .iter()
            .any(|alignment| alignment.len() != last_refresh.len())
    {
        return Vec::new();
    }
    let mut picked = Vec::with_capacity(view_alignments.len() + 1);
    for alignment in view_alignments {
        let best = alignment
            .iter()
            .enumerate()
            .max_by(|(a_index, a), (b_index, b)| a.total_cmp(b).then_with(|| b_index.cmp(a_index)))
            .filter(|(_, alignment)| **alignment > 0.45)
            .map(|(index, _)| index);
        if let Some(index) = best {
            if !picked.contains(&index) {
                picked.push(index);
            }
        }
    }
    if let Some((stale, _)) = last_refresh
        .iter()
        .enumerate()
        .filter(|(index, _)| !picked.contains(index))
        .min_by_key(|&(index, &last)| (last, index))
    {
        picked.push(stale);
    }
    picked
}

/// Whether any camera rendered by this process can currently see a live Tiger periscope screen.
/// In couch mode the keyboard player's `station` is not authoritative for all four simultaneous
/// views: a surviving Loader still needs the atlas even after P1 has taken over the Gunner post.
fn rtt_has_inside_viewer(
    couch_active: bool,
    couch_commander_occupied: bool,
    couch_loader_occupied: bool,
    couch_hull_occupied: bool,
    station: Station,
    commander_outside: bool,
) -> bool {
    if couch_active {
        (couch_commander_occupied && !commander_outside) || couch_loader_occupied || couch_hull_occupied
    } else {
        matches!(station, Station::Commander | Station::Loader | Station::Driver | Station::Radioman)
            && !(matches!(station, Station::Commander) && commander_outside)
    }
}

/// What one pen-ray hop terminated on (fire-time resolution, docs/DESTRUCTION.md §3).
#[cfg(any())]
enum HopHit {
    Enemy(usize),
    Struct(usize),
    HardCover,
    Tree(usize),
    Terrain,
    Nothing,
}

/// Opaque world geometry shared by the non-penetrating player-MG ray and enemy shell ray. The
/// caller decides the consequence (MG stops; a cannon shell damages/fells destructible cover), but
/// both weapons must agree on which physical thing was nearest.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CoverRayHit {
    Terrain,
    Static,
    Struct(usize),
    Tree(usize),
}

/// Wall-transit properties for the AP pen ray (docs/DESTRUCTION.md §3.1): what one pass through
/// this material costs the round. `cost_mm` spends the pen budget; `deflect_mrad` is the hashed
/// angular kick (miss distance grows with the wall→target gap for free); `disrupt` models yaw +
/// cap stripping — it multiplies the round's effective pen DOWN at the terminal armor hit.
#[derive(Clone, Copy)]
struct ApTransit {
    cost_mm: f32,
    deflect_mrad: f32,
    disrupt: f32,
}

impl Material {
    fn ap(self) -> ApTransit {
        match self {
            Material::Timber => ApTransit {
                cost_mm: 12.0,
                deflect_mrad: 5.0,
                disrupt: 0.0,
            },
            Material::Brick => ApTransit {
                cost_mm: 35.0,
                deflect_mrad: 15.0,
                disrupt: 0.30,
            },
            Material::Stone => ApTransit {
                cost_mm: 70.0,
                deflect_mrad: 25.0,
                disrupt: 0.60,
            },
            Material::Bunker => ApTransit {
                cost_mm: 9999.0,
                deflect_mrad: 0.0,
                disrupt: 1.0,
            },
        }
    }
}

// AP is structurally LIGHT (a hole, not a collapse); HE does the demolition (radial, with
// falloff). One shell type used to flat-rate 55 HP — the natures split it.
const STRUCT_AP_HOLE_DAMAGE: f32 = 15.0; // a clean transit punch-through
const STRUCT_AP_TERMINAL_DAMAGE: f32 = 30.0; // the round DIED in this wall — bigger bite
const HE_STRUCT_DAMAGE: f32 = 85.0; // radial peak at the burst — one-shots a small wall
const HE_BLAST_RADIUS: f32 = 7.0; // m — structure/tree damage radius
const TREE_AP_COST_SMALL: f32 = 3.0; // mm — a fir barely registers on the budget
const TREE_AP_COST_BIG: f32 = 15.0; // mm — a mature trunk eats a little
#[cfg(any())]
const PEN_RAY_MAX_HOPS: usize = 6; // walls a single round can chain through

const TIMBER_BURST_SPEED: f32 = 2.2; // m/s — above this, tier-1 pieces burst instead of grinding
const CRUSH_NOSE_R: f32 = 1.4; // m — bow contact radius (Tiger hull is ~3.7 m wide)
const CRUSH_NOSE_LEN: f32 = 3.2; // m — hull pivot → bow, along the direction of travel

/// Bow-circle vs wall-AABB contact in the ground plane: `Some((push, overlap))` when the nose
/// circle penetrates the box, where `push` is the outward XZ unit-ish vector that separates it.
/// Degenerate fully-inside case pushes back along `-dir`. Pure so the contact test is unit-testable.
/// True when a box lies wholly at or below the terrain surface over its footprint (its top below
/// the lowest terrain height at its corners and centre): buried, so nothing riding on the terrain
/// can touch it. Sealed cellar storeys are buried this way until terrain openings exist.
fn buried_below_ground(hf: &Heightfield, min: Vec3, max: Vec3) -> bool {
    let center = (min + max) * 0.5;
    let ground = [
        (min.x, min.z),
        (max.x, min.z),
        (min.x, max.z),
        (max.x, max.z),
        (center.x, center.z),
    ]
    .into_iter()
    .map(|(x, z)| hf.height_at(x, z))
    .fold(f32::INFINITY, f32::min);
    max.y <= ground
}

fn nose_contact(nose: Vec3, dir: Vec3, min: Vec3, max: Vec3) -> Option<(Vec3, f32)> {
    let cx = nose.x.clamp(min.x, max.x);
    let cz = nose.z.clamp(min.z, max.z);
    let (dx, dz) = (nose.x - cx, nose.z - cz);
    let d2 = dx * dx + dz * dz;
    if d2 >= CRUSH_NOSE_R * CRUSH_NOSE_R {
        return None;
    }
    if d2 < 1e-6 {
        // Nose centre is inside the box (a fast frame skipped the skin) — back straight out.
        return Some((-Vec3::new(dir.x, 0.0, dir.z), CRUSH_NOSE_R));
    }
    let d = d2.sqrt();
    Some((Vec3::new(dx / d, 0.0, dz / d), CRUSH_NOSE_R - d))
}

// ── Campaign / skirmish OPENING geometry: spawn on the player's terms, the wind field, the dead ──
// The engagement opens with the Tiger mustered FAR OUT on the open Volga steppe, well SOUTH of the
// ruined city, hull facing NORTH (+Z) toward the ruins — and CRUCIALLY out of contact: at t=0 every
// enemy sits beyond the stationary detection radius (`stealth::RADIUS_STILL`), so a still Tiger is a
// grey ghost the half-blind swarm cannot see and can sit at spawn undetected indefinitely. This is
// deliberate — once T-34s close on a lone Tiger it is over, so the fight MUST start at sniper range on
// the player's terms: you DRIVE IN across the empty snow to bring the enemy into your gunsight, not the
// other way round. The swarm rings the city to the north — the OUTSKIRTS platoon is the near picket
// line the driving player meets first (at long range — Tigers were snipers, so the spacing is held);
// the IN-CITY platoon is dug DEEPER into the streets behind the building cover (partially concealed —
// the stealth LOS respects those occluders), reached only after the approach. The split falls on the
// platoon boundary so the stealth model's contiguous PLATOON_SIZE=3 groups each muster wholly in one
// zone. Frozen bodies thicken toward the city edge, sparse out on the open approach. A cold steppe wind
// blows hard over the open ground and is broken by the city canyon.

/// World (x, z) the player Tiger musters at — FAR out on the open steppe, well south of the built-up
/// area, hull facing +Z (north) toward the city. Held beyond every enemy's stationary detection radius
/// so the fight opens UNDETECTED and the player drives in to make contact (see the scenario note
/// above). Shared by `Game::build` and the spawn-layout test.
const PLAYER_SPAWN: (f32, f32) = (-30.0, -560.0);

/// The parametric city's grid centre (packed x, z), north of the spawn. Shared by `city::generate`
/// (the ruins the player faces) and `wind_at` (the canyon that shelters the wind).
const CITY_CENTER: Vec2 = Vec2::new(-30.0, 110.0);

/// Which combat zone a swarm member musters in. OUTSKIRTS tanks sit out on the open steppe at sniper
/// range (the classic long approach); IN-CITY tanks are dug into the ruins behind the building cover
/// (partially concealed — the stealth LOS already respects those occluders). The split lands on the
/// platoon boundary so each PLATOON_SIZE=3 platoon is wholly one or the other.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
enum SpawnZone {
    Outskirts,
    InCity,
}

/// Muster points (world x, z) + zone for the swarm — the OPENING array (see the scenario note above).
/// Platoon 0 (0,1,2) = OUTSKIRTS: the near sniper picket ring around the city's southern approach,
/// ~575-580 m out from the far spawn (all beyond the ~450 m stationary detection radius, so the player
/// makes NO contact until it drives in); platoon 1 (3,4,5) = IN-CITY, dug DEEPER into the northern
/// streets among the ruins, ~685-705 m out (met only after pushing into the city). Headings are derived
/// toward the player at spawn time.
const SWARM: [(f32, f32, SpawnZone); N_ENEMIES] = [
    // OUTSKIRTS — the sniper picket ring on the open ground around the city's southern approach; the
    // first (long-range) contact the driving player makes. All ~575-580 m from spawn (> RADIUS_STILL).
    (-160.0, 5.0, SpawnZone::Outskirts), // south-west flank picket
    (110.0, 5.0, SpawnZone::Outskirts),  // south-east flank picket
    (-50.0, 15.0, SpawnZone::Outskirts), // southern approach picket — dead ahead down the drive-in axis
    // IN-CITY — dug DEEPER into the northern streets, behind facades (city occluders partially conceal
    // them). Reached only after the approach; ~685-705 m from spawn (deeper than the outskirts ring).
    (-45.0, 125.0, SpawnZone::InCity), // deep north-west street intersection
    (-15.0, 125.0, SpawnZone::InCity), // deep north-east street intersection
    (-45.0, 143.0, SpawnZone::InCity), // deepest — far north-west street, well into the ruins
];

/// Per-swarm-member vehicle kind, PARALLEL to `SWARM` (kept separate so the spawn-layout test's tuple
/// destructuring is untouched). The two OUTSKIRTS FLANK pickets (#0 SW, #1 SE) are SU-100 tank
/// destroyers standing OVERWATCH at long standoff — the sniper counter to the T-34 rush: their 100 mm
/// D-10S defeats the Tiger's frontal plate at range, and they hold back / reposition instead of
/// charging (see `overwatch_maneuver`). The southern-approach picket (#2) and the whole IN-CITY
/// platoon (#3,4,5) are T-34-76s that advance + flank. This keeps platoon 0 a mixed sniper-screen and
/// platoon 1 a pure rush, without disturbing the PLATOON_SIZE=3 stealth grouping.
const SWARM_KINDS: [EnemyKind; N_ENEMIES] = [
    EnemyKind::Su100, // #0 SW flank — overwatch sniper
    EnemyKind::Su100, // #1 SE flank — overwatch sniper
    EnemyKind::T34,   // #2 southern approach picket
    EnemyKind::T34,   // #3 in-city
    EnemyKind::T34,   // #4 in-city
    EnemyKind::T34,   // #5 in-city
];

/// Choose the physical opening roster before constructing either tanks or their visible rigs.
/// The standalone range has no enemy anchors, so it must not inherit the campaign's SU-100 pair.
fn opening_enemy_swarm(playtest: bool) -> Vec<(f32, f32, SpawnZone, EnemyKind, bool)> {
    SWARM
        .iter()
        .zip(SWARM_KINDS)
        .enumerate()
        .map(|(i, (&(x, z, zone), kind))| {
            if playtest {
                (
                    [-110.0, 0.0, 110.0][i % 3],
                    -160.0 - (i / 3) as f32 * 65.0,
                    SpawnZone::Outskirts,
                    EnemyKind::T34,
                    true,
                )
            } else {
                (x, z, zone, kind, false)
            }
        })
        .collect()
}

fn opening_enemy_reload(playtest: bool, index: usize) -> f32 {
    if playtest {
        8.0 + index as f32 * 1.2
    } else {
        ENEMY_RELOAD * (index as f32 + 0.5) / N_ENEMIES as f32
    }
}

/// Retain the practice range's distances on whichever authored map owns the player spawn.
/// Search is startup-only and bounded; targets never fall back into blocked structures.
fn playtest_target_positions(spawn: Vec2, half_extent: f32,
    mut clear: impl FnMut(Vec2) -> bool) -> [Option<Vec2>; N_ENEMIES] {
    let mut placed = [None; N_ENEMIES];
    for (index, (x, z, _, _, _)) in opening_enemy_swarm(true).into_iter().enumerate() {
        let preferred = spawn + Vec2::new(x, z - 180.0);
        let offset = preferred - spawn;
        let bearing = offset.y.atan2(offset.x);
        let nearby = (0..128).map(|sample| {
            let radius = (sample / 16 + 1) as f32 * 8.0;
            let angle = (sample % 16) as f32 * std::f32::consts::TAU / 16.0;
            preferred + Vec2::new(angle.cos(), angle.sin()) * radius
        });
        let alternate = (0..576).map(|sample| {
            let radius = [offset.length(), 340.0, 360.0, 380.0, 400.0, 420.0][sample / 96];
            let step = sample % 96;
            let turn = ((step + 1) / 2) as f32 * if step % 2 == 0 { -1.0 } else { 1.0 };
            let angle = bearing + turn * std::f32::consts::TAU / 96.0;
            spawn + Vec2::new(angle.cos(), angle.sin()) * radius
        });
        placed[index] = std::iter::once(preferred).chain(nearby).chain(alternate).find(|&point| {
            let range = point.distance(spawn);
            point.abs().max_element() <= half_extent - 8.0
                && (339.99..=420.01).contains(&range)
                && placed[..index].iter().flatten().all(|other: &Vec2| point.distance(*other) >= 24.0)
                && clear(point)
        });
    }
    placed
}

fn configure_playtest_return_fire(
    setting: &mut Option<bool>,
    enemies: &mut [Tank],
    enabled: bool,
) {
    let Some(current) = setting else { return; };
    if *current == enabled { return; }
    *current = enabled;
    if enabled {
        // A pause-menu toggle must not release six ready guns in the very first resumed frame.
        for (i, enemy) in enemies.iter_mut().enumerate() {
            enemy.reload = enemy.reload.max(opening_enemy_reload(true, i));
        }
    }
}

fn settle_stationary_target(enemy: &mut Tank, dt: f32, hf: &Heightfield) {
    // Zero orders use the same physical deceleration as releasing the controls; no pose teleport.
    enemy.update(0.0, 0.0, 0.0, 0.0, dt, hf);
}

// ── SU-100 overwatch-sniper standoff band (metres) ───────────────────────────────────────────────
// The SU-100 is a long-range sniper, NOT a brawler: it holds inside this range band and turns its
// HULL to lay the fixed casemate gun. If the Tiger closes inside the min, it REVERSES to keep the
// range (never charges); if the Tiger drifts beyond the max, it creeps forward to re-establish LOS.
const SU100_STANDOFF_MIN: f32 = 280.0; // m — closer than this ⇒ back off to keep range
const SU100_STANDOFF_MAX: f32 = 520.0; // m — farther than this ⇒ creep in to hold LOS

// ── Zoned wind field ─────────────────────────────────────────────────────────────────────────────
// Act-scale directions and measured speed ranges live in world.rs. Only Act I uses the city-canyon
// exposure transition below; the Oderbruch is exposed and Halbe sits beneath a dense forest canopy.
const WIND_SHELTER_R: f32 = 58.0; // ~city-core radius over which the shelter fades to full open wind

/// Local horizontal wind at a world position, as a ground-plane (x, z) vector in m/s. A slow,
/// purely spatial variation keeps the field from reading dead-uniform. Pure + deterministic (no
/// rand, no time), this drives weather, volumetric smoke and wreck flame identically in every view.
fn legacy_stalingrad_layers_enabled(act_id: u8) -> bool {
    act_id == 1
}

// Scene workshops own every placed object. Campaign and combat playtests keep their
// procedural population; a reusable authored assembly must not acquire unrelated traces.
fn isolated_authored_scene(mode: Option<&str>) -> bool {
    mode == Some("scene")
}

fn campaign_day_phase(_act_id: u8, night: bool) -> DayPhase {
    if night {
        DayPhase::Night
    } else {
        DayPhase::Day
    }
}

fn wind_at(act_id: u8, pos: Vec3) -> Vec2 {
    let p = Vec2::new(pos.x, pos.z);
    let profile = crate::world::weather_wind_profile(act_id);
    let exposure = match act_id {
        1 => smoothstep(
            WIND_SHELTER_R * 0.45,
            WIND_SHELTER_R * 1.4,
            p.distance(CITY_CENTER),
        ),
        2 => 1.0,
        3 => 0.0,
        _ => 1.0,
    };
    let speed = profile.sheltered_speed_m_s
        + (profile.exposed_speed_m_s - profile.sheltered_speed_m_s) * exposure;
    let phase = p.x * 0.011 + p.y * 0.017 + f32::from(act_id) * 1.731;
    let spatial = 1.0 + profile.spatial_variation * phase.sin();
    profile.direction * (speed * spatial)
}

/// Smoke-plume drift direction for a local wind (`wind_at` output): a strong upward loft with a
/// downwind lean scaled by the wind strength. The renderer normalizes this and adds its own loft, so
/// only the lean RATIO matters — a hard open-steppe wind lays the column over, a sheltered street
/// wind lets it rise almost straight.
fn smoke_drift(wind: Vec2) -> Vec3 {
    Vec3::new(wind.x * 0.14, 1.0, wind.y * 0.14)
}

/// A single frozen corpse, prone in the snow, built from flat-shaded boxes (matching the engine's
/// procedural-box set-dressing style — no import pipeline). Local frame: the body lies along +Z (head
/// toward +Z), y=0 at the snow contact, so a placement transform just yaws + grounds it. `color` is a
/// snow-dusted greatcoat tint. One mesh (merged boxes, one solid tint) so it clones cheaply per body.
fn corpse_mesh(color: [u8; 3]) -> CpuMesh {
    // torso, head, two legs, two splayed arms — a hunched soldier fallen face-down in the drift.
    let boxes: [(Vec3, Vec3); 6] = [
        (Vec3::new(-0.24, 0.0, -0.30), Vec3::new(0.24, 0.26, 0.40)), // torso
        (Vec3::new(-0.13, 0.0, 0.40), Vec3::new(0.13, 0.20, 0.66)),  // head
        (Vec3::new(-0.22, 0.0, -0.95), Vec3::new(-0.02, 0.18, -0.28)), // left leg
        (Vec3::new(0.02, 0.0, -0.95), Vec3::new(0.22, 0.18, -0.28)), // right leg
        (Vec3::new(-0.46, 0.0, -0.02), Vec3::new(-0.24, 0.13, 0.34)), // left arm (splayed)
        (Vec3::new(0.24, 0.0, -0.02), Vec3::new(0.46, 0.13, 0.34)),  // right arm
    ];
    let mut verts: Vec<crate::gltf_load::Vertex> = Vec::new();
    let mut idx: Vec<u32> = Vec::new();
    let mut mn = Vec3::splat(f32::INFINITY);
    let mut mx = Vec3::splat(f32::NEG_INFINITY);
    for (lo, hi) in boxes {
        let b = box_mesh(lo, hi, color);
        let base = verts.len() as u32;
        verts.extend_from_slice(&b.vertices);
        idx.extend(b.indices.iter().map(|i| base + i));
        mn = mn.min(lo);
        mx = mx.max(hi);
    }
    CpuMesh::basic(verts, idx, Some(crate::prims::solid_color(color)), mn, mx)
}

/// Rigid low-poly Soviet placeholder: greatcoat, ushanka, arms, separated legs and boots.
fn soviet_infantry_mesh(color: [u8; 3]) -> CpuMesh {
    let boxes: [(Vec3, Vec3); 10] = [
        (Vec3::new(-0.23, 0.82, -0.15), Vec3::new(0.23, 1.42, 0.15)),
        (Vec3::new(-0.28, 0.54, -0.18), Vec3::new(0.28, 0.88, 0.18)),
        (Vec3::new(-0.14, 1.42, -0.12), Vec3::new(0.14, 1.68, 0.12)),
        (Vec3::new(-0.19, 1.64, -0.15), Vec3::new(0.19, 1.75, 0.15)),
        (Vec3::new(-0.34, 0.88, -0.10), Vec3::new(-0.22, 1.34, 0.10)),
        (Vec3::new(0.22, 0.88, -0.10), Vec3::new(0.34, 1.34, 0.10)),
        (Vec3::new(-0.21, 0.16, -0.12), Vec3::new(-0.035, 0.60, 0.12)),
        (Vec3::new(0.035, 0.16, -0.12), Vec3::new(0.21, 0.60, 0.12)),
        (Vec3::new(-0.23, 0.0, -0.22), Vec3::new(-0.025, 0.18, 0.14)),
        (Vec3::new(0.025, 0.0, -0.22), Vec3::new(0.23, 0.18, 0.14)),
    ];
    let mut verts = Vec::new();
    let mut idx = Vec::new();
    let mut mn = Vec3::splat(f32::INFINITY);
    let mut mx = Vec3::splat(f32::NEG_INFINITY);
    for (lo, hi) in boxes {
        let b = box_mesh(lo, hi, color);
        let base = verts.len() as u32;
        verts.extend_from_slice(&b.vertices);
        idx.extend(b.indices.iter().map(|i| base + i));
        mn = mn.min(lo);
        mx = mx.max(hi);
    }
    CpuMesh::basic(verts, idx, Some(crate::prims::solid_color(color)), mn, mx)
}

/// Load the authored Soviet pose library as one transaction. A missing, corrupt, untextured, or
/// topology-inconsistent frame rejects the whole set so play can never mix the selected character
/// with procedural body parts. The procedural presentation remains the explicit fallback.
fn load_exact_soviet_pose_meshes() -> anyhow::Result<[CpuMesh; SOVIET_POSE_COUNT]> {
    let mut meshes = Vec::with_capacity(SOVIET_POSE_COUNT);
    let mut expected_atlas: Option<(u32, u32, Vec<u8>)> = None;

    for path in SOVIET_POSE_PATHS {
        let mesh = crate::gltf_load::load_glb(path)
            .map_err(|error| anyhow::anyhow!("could not load Soviet pose {path}: {error:#}"))?;
        anyhow::ensure!(
            mesh.indices.len() >= 3 && mesh.indices.len() % 3 == 0,
            "Soviet pose {path} has invalid triangle topology"
        );
        anyhow::ensure!(
            mesh.indices
                .iter()
                .all(|&index| index < mesh.vertices.len() as u32),
            "Soviet pose {path} contains an out-of-range index"
        );
        anyhow::ensure!(
            mesh.vertices.iter().all(|vertex| {
                vertex
                    .pos
                    .iter()
                    .chain(vertex.normal.iter())
                    .chain(vertex.uv.iter())
                    .chain(vertex.tangent.iter())
                    .all(|value| value.is_finite())
            }),
            "Soviet pose {path} contains non-finite vertex data"
        );
        let extent = mesh.max - mesh.min;
        anyhow::ensure!(
            mesh.min.is_finite()
                && mesh.max.is_finite()
                && extent.min_element() > 0.001
                && mesh.metallic_factor.is_finite()
                && mesh.roughness_factor.is_finite(),
            "Soviet pose {path} has invalid bounds or material factors"
        );
        let atlas = mesh
            .texture
            .as_ref()
            .ok_or_else(|| anyhow::anyhow!("Soviet pose {path} has no base-color atlas"))?;
        anyhow::ensure!(
            atlas.width > 0
                && atlas.height > 0
                && atlas.rgba.len() == atlas.width as usize * atlas.height as usize * 4,
            "Soviet pose {path} has an invalid base-color atlas"
        );

        // Deformed normal seams legitimately split a different number of glTF vertices.
        // All 17 supplied-source derivatives were independently audited to retain the same
        // oriented UV triangles (including the generated rifle), so compare that surface.
        // Receipt: artifacts/astra-audit-20260905/soviet-user-runtime-surface-20260905.json.
        anyhow::ensure!(
            mesh.indices.len() == 6_252
                && infantry_pose_runtime::triangle_uv_fingerprint(&mesh) == 0x300dfe27948b96d0,
            "Soviet pose {path} changed audited triangle coverage, winding or UVs"
        );
        if let Some((width, height, rgba)) = expected_atlas.as_ref() {
            anyhow::ensure!(
                atlas.width == *width
                    && atlas.height == *height
                    && atlas.rgba.as_slice() == rgba.as_slice(),
                "Soviet pose {path} does not use the shared source atlas"
            );
        } else {
            expected_atlas = Some((atlas.width, atlas.height, atlas.rgba.as_ref().clone()));
        }
        meshes.push(mesh);
    }

    meshes.try_into().map_err(|meshes: Vec<CpuMesh>| {
        anyhow::anyhow!(
            "Soviet pose set loaded {} frames, expected {SOVIET_POSE_COUNT}",
            meshes.len()
        )
    })
}

