#[derive(Default, Clone, Copy)]
pub struct TankInput {
    pub drive: f32,    // W/S  [-1,1]
    pub steer: f32,    // A/D
    pub traverse: f32, // ←/→
    pub elevate: f32,  // ↑/↓
    pub fire: bool,    // Space
    /// Held MG34 trigger (Left Shift). ONE trigger, routed by view: in the gunner optic it fires
    /// the COAXIAL MG (parallel to the main gun); in the commander view it chatters the HULL/BOW MG.
    /// The player mans whichever MG their current station covers (single-crew simplification).
    pub mg_coax: bool,
    /// Held C — the coax MG trigger at the GUNNER's sights. (It rode Ctrl until the playtest made
    /// Ctrl the EXIT-the-sights key; LMB there is the main gun, so the coax needed its own finger.)
    pub coax: bool,
    pub look_dx: f32, // mouse delta this frame (commander head-look)
    pub look_dy: f32,
    pub binoculars: bool, // right mouse held (commander / on-foot Luger aim)
    /// F held — grab the extinguisher and knock down the interior fire (locks ALL stations while it
    /// runs). The genuine race against the ammo cook-off (`fire_ammo_timer`).
    pub extinguish: bool,
    /// R held — field-repair the highest-priority repairable downed module the current station reaches
    /// (also locks all stations; tracks need the driver hatched out).
    pub repair: bool,
    pub run: bool, // legacy (running is the DEFAULT gait on foot now; crouch is the slow one)
    pub aim: bool, // right mouse HELD — on-foot weapon aim / seated Driver lean toward visor
    pub fire2: bool, // left mouse — on-foot Luger fire
    pub crouch: bool, // ctrl — on-foot crouch (lower eye, slower, quieter, smaller target)
    pub reload: bool, // R — on-foot Luger magazine change
    pub jump: bool, // Space: chassis, roof, open hatch or cabin; otherwise jump on foot
    pub ignition: bool, // Z — engine shutoff / crank (the silent-watch scout loop)
    pub hatch_toggle: bool, // occupied station hatch request; shared solo/LAN rising edge
    /// LAN crew authority for this frame. `None` preserves the exact solo control path. When set,
    /// simulation duties come from their real stations while this process's ordinary input remains
    /// the local crewman's camera/body input.
    pub coop: Option<crate::lan::CrewFrame>,
    pub coop_host: bool,
    /// This `CrewFrame` belongs to the single-machine four-person couch mode. Unlike LAN (whose
    /// historical behavior remains unchanged), occupied posts are physical mortal bodies: a
    /// penetrating hit can kill one peer while the remaining crew keeps the Tiger fighting.
    pub couch_crew: bool,
    /// Immutable peer -> person/face bindings for couch mode. Authority and physical `post` may
    /// change after a takeover; these slots may not.
    pub couch_identities: CouchCrewIdentities,
}

/// A bounded cursor over a wrapping authoritative discharge counter. The first observation is a
/// baseline (joining a battle must not replay its history), repeats are deduplicated, and a large
/// backwards/reset jump is rebased instead of being mistaken for billions of wrapped events.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct ShotSequenceCursor {
    last: Option<u32>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ShotSequenceAdvance {
    pub first: u32,
    pub count: u32,
}

impl ShotSequenceAdvance {
    pub fn iter(self) -> impl Iterator<Item = u32> {
        (0..self.count).map(move |offset| self.first.wrapping_add(offset))
    }
}

impl ShotSequenceCursor {
    /// A film recorder knows its baseline before its first simulation tick, unlike a joining LAN
    /// client whose first received snapshot must establish that baseline via [`Self::observe`].
    pub fn at(sequence: u32) -> Self {
        Self {
            last: Some(sequence),
        }
    }

    pub fn clear(&mut self) {
        self.last = None;
    }

    pub fn observe(&mut self, sequence: u32) -> Option<ShotSequenceAdvance> {
        const MAX_CATCH_UP: u32 = 64;
        let Some(previous) = self.last.replace(sequence) else {
            return None;
        };
        let count = sequence.wrapping_sub(previous);
        if count == 0 || count > MAX_CATCH_UP {
            return None;
        }
        Some(ShotSequenceAdvance {
            first: previous.wrapping_add(1),
            count,
        })
    }
}

fn campaign_ai_command_input(
    mode: Mode,
    foot_yaw: f32,
    command: crate::campaign_ai::CampaignAiCommand,
) -> TankInput {
    match mode {
        Mode::Tank => TankInput {
            drive: command.tank_drive,
            steer: command.tank_steer,
            ..TankInput::default()
        },
        Mode::Foot => {
            let look_dx = command.foot_target_yaw.map_or(0.0, |target| {
                let error = (target - foot_yaw + std::f32::consts::PI)
                    .rem_euclid(std::f32::consts::TAU)
                    - std::f32::consts::PI;
                // A bounded mouse-equivalent turn keeps the controller physical while converging
                // quickly enough that fixed-step training is not dominated by in-place rotation.
                error.clamp(-0.12, 0.12) / crate::foot::SENS
            });
            TankInput {
                drive: command.foot_forward,
                // FootSoldier uses D-A strafe while TankInput steer is A-D.
                steer: -command.foot_strafe,
                look_dx,
                crouch: command.crouch,
                reload: command.search_map,
                ..TankInput::default()
            }
        }
    }
}

#[derive(Clone, Copy)]
struct TigerFootPolicyContext {
    observation: FootObservation,
    target_visible: bool,
    target_right: f32,
    can_fire: bool,
    can_reload: bool,
    can_interact: bool,
    can_jump: bool,
    panzerfaust_available: bool,
    current_weapon: WeaponSelection,
    weapon_switch_allowed: bool,
}

fn gate_tiger_foot_action(
    proposed: FootAction,
    context: TigerFootPolicyContext,
    force_mission_interact: bool,
) -> FootAction {
    let desired_weapon = match proposed.weapon {
        WeaponSelection::AntiTank if context.panzerfaust_available => WeaponSelection::AntiTank,
        _ => WeaponSelection::Sidearm,
    };
    let weapon = if context.weapon_switch_allowed || desired_weapon == context.current_weapon {
        desired_weapon
    } else {
        context.current_weapon
    };
    FootAction {
        forward: proposed.forward.clamp(-1.0, 1.0),
        strafe: proposed.strafe.clamp(-1.0, 1.0),
        turn: proposed.turn.clamp(-1.0, 1.0),
        crouch: proposed.crouch,
        aim: proposed.aim && context.target_visible,
        fire: proposed.fire
            && proposed.aim
            && context.target_visible
            && context.can_fire
            && context.target_right.abs() < 0.18,
        reload: proposed.reload && context.can_reload,
        interact: force_mission_interact || (proposed.interact && context.can_interact),
        jump: proposed.jump && context.can_jump,
        weapon,
    }
}

fn tiger_foot_action_input(action: FootAction) -> TankInput {
    TankInput {
        drive: action.forward,
        // FootSoldier consumes D-A while TankInput steer is A-D.
        steer: -action.strafe,
        // Same physical mouselook path as a human; 0.12 rad/frame is the existing controller cap.
        look_dx: action.turn * 0.12 / crate::foot::SENS,
        aim: action.aim,
        fire2: action.fire,
        crouch: action.crouch,
        reload: action.reload || action.interact,
        jump: action.jump,
        ..TankInput::default()
    }
}

/// Inside-view hotspots: click mechanisms/tools; hold LMB for physical ammunition.
#[derive(Clone, Copy, PartialEq, Debug)]
enum Hotspot {
    GunLever,          // one LMB click opens or closes the breech
    LoadedRound,       // lever open: pull the live round back out to change ammunition
    RackSlot(usize),   // grab THIS round off the rack (index into interior_rig::SHELL_SLOTS)
    SpentCasing,       // the hot case sitting in the spent breech — hold LMB to pull it free
    FloorShell(usize), // a dropped round rolling on the basket floor — pick it back up
    FloorCasing(usize), // dropped brass uses the same held grip and release as a fresh case
    Extinguisher,      // click equips, subsequent held press sprays
    RepairKit,         // click equips the persistent tool kit
    PanzerfaustRack(usize), // the exact full-size tube under the crosshair
    Ignition,          // small physical engine start/stop button
    DriverVisor,       // source handwheel: click toggles opposed shields, independently of roof H
}

/// Picking uses the same low-poly cartridge body as rendering (AP and HE share geometry).
/// The broad bounds only reject misses; a pointed-tip empty corner is never a pickup target.
/// This chooses among physical ammunition bodies, not a complete scene-occlusion query.
fn ray_loader_round(eye: Vec3, direction: Vec3, model: Mat4, reach: f32) -> Option<f32> {
    static ROUND: std::sync::OnceLock<crate::gltf_load::CpuMesh> = std::sync::OnceLock::new();
    let mesh = ROUND.get_or_init(crate::procedural_ordnance::ap_round_mesh);
    ray_loader_ammunition_mesh(eye, direction, model, reach, mesh)
}

fn ray_loader_case(eye: Vec3, direction: Vec3, model: Mat4, reach: f32) -> Option<f32> {
    static CASE: std::sync::OnceLock<crate::gltf_load::CpuMesh> = std::sync::OnceLock::new();
    let mesh = CASE.get_or_init(crate::procedural_ordnance::spent_case_mesh);
    ray_loader_ammunition_mesh(eye, direction, model, reach, mesh)
}

fn ray_loader_ammunition_mesh(eye: Vec3, direction: Vec3, model: Mat4, reach: f32,
    mesh: &crate::gltf_load::CpuMesh) -> Option<f32>
{
    let inverse = model.inverse();
    let origin = inverse.transform_point3(eye);
    let dir = inverse.transform_vector3(direction);
    if !origin.is_finite() || !dir.is_finite() || dir.length_squared() < 1.0e-10 {
        return None;
    }
    ray_aabb_near(origin, dir, mesh.min, mesh.max, reach, 0.0)?;
    let mut nearest = reach;
    let mut found = false;
    for triangle in mesh.indices.chunks_exact(3) {
        let a = Vec3::from_array(mesh.vertices[triangle[0] as usize].pos);
        let b = Vec3::from_array(mesh.vertices[triangle[1] as usize].pos);
        let c = Vec3::from_array(mesh.vertices[triangle[2] as usize].pos);
        let edge1 = b - a;
        let edge2 = c - a;
        let cross = dir.cross(edge2);
        let determinant = edge1.dot(cross);
        if determinant.abs() < 1.0e-8 { continue; }
        let offset = origin - a;
        let u = offset.dot(cross) / determinant;
        if !(0.0..=1.0).contains(&u) { continue; }
        let q = offset.cross(edge1);
        let v = dir.dot(q) / determinant;
        if v < 0.0 || u + v > 1.0 { continue; }
        let distance = edge2.dot(q) / determinant;
        if distance > 0.0 && distance <= nearest {
            nearest = distance;
            found = true;
        }
    }
    found.then_some(nearest)
}

/// Which mesh rides the loader's hands while a round is carried (the very shell you grabbed
/// leaves its rack slot / floor spot and follows the carry spring — nothing teleports).
#[derive(Clone, Copy, PartialEq)]
enum CarriedMesh {
    RackShell(usize),  // renderer slot shell0 + i keeps drawing, at the carry transform
    LooseShell(usize), // a scooped floor round: its loose_shell slot keeps drawing
}

impl CarriedMesh {
    /// Location IDs shared with `live_ammunition_in_frame`; hands retain the source location.
    fn ammunition_location_id(self) -> u32 {
        match self {
            Self::RackShell(index) => index as u32,
            Self::LooseShell(index) => 0x2_0000 + index as u32,
        }
    }
    fn reserved_rack_slot(self) -> Option<usize> {
        match self { Self::RackShell(index) => Some(index), Self::LooseShell(_) => None }
    }

    fn floor_slot(self, loose: &[LooseShell]) -> Option<usize> {
        match self {
            Self::LooseShell(index) => Some(index),
            Self::RackShell(_) => loose.iter().position(|shell| !shell.active),
        }
    }

    fn nature_he(self, rack_nature: &[bool], loose: &[LooseShell]) -> bool {
        match self {
            Self::RackShell(index) => rack_nature[index],
            Self::LooseShell(index) => loose[index].nature_he,
        }
    }
}

/// A dropped main-gun round, stored in the turret frame. Full orientation and angular momentum
/// survive release; finite source contacts supply gravity support, bounce, friction and rolling.
#[derive(Clone, Copy, Default)]
struct LooseShell {
    active: bool,
    world_space: bool, // salvaged/exterior bodies remain fixed when the player tank moves
    pos: Vec3, // turret-local
    vel: Vec3, // turret-local m/s
    rotation: Quat, // complete rigid orientation, turret-local
    angular_vel: Vec3, // turret-local rad/s, carried through release and contact
    nature_he: bool,
    drop_rest: shell_collision::DropRest,
    impact_cooldown: f32,
}

// Every cartridge in the initial physical inventory can be set down without deleting another
// round: 65 rack bodies plus the chamber body. Inactive slots stay hidden; there is no auto-stow.
const N_LOOSE: usize = crate::interior_rig::SHELL_SLOTS.len() + 1 + wreck_salvage::MAX_SALVAGE_ROUNDS;
/// A short, articulated visual run for the loose end the player drags back over the road wheels.
const N_REPAIR_SHOES: usize = 18;
const BASKET_FLOOR: f32 = crate::interior_rig::FLOOR_STAND_Y
    + crate::procedural_ordnance::LIVE_MAX_DIAMETER_M * 0.5;

// ── Crew-of-one interior workload: STATIONS, MANUAL RELOAD, FIRE-FIGHTING, REPAIR ─────────────────
// The scarce resource is the one player's HANDS, expressed as `station` (the posted seat whose
// continuous controls are live) + `activity` (a discrete emergency beat — extinguish / repair — that
// yanks both hands off any station). Manual reload is a station duty at the breech (Loader): eject a
// hot casing, then MASH a fresh round home. The existing 5 crew `ok` flags gate speed, not the
// player: an ok crewman means the job runs assisted/fast, a KO'd one means the lone survivor does it
// himself, degraded (slower ram, a manual eject fumble) — never impossible.

/// Seconds to move BETWEEN seats: within the turret (gunner↔loader↔commander) vs clambering to the
/// hull driver's seat (through the turret basket) — the whole point is that switching costs a beat.
const SWITCH_TURRET: f32 = 0.55;
const SWITCH_HULL: f32 = 0.95;
/// Ram progress (0..1) added per Space mash: assisted (loader ok) seats in ~3 mashes; one-handed
/// (loader KO'd) takes ~7-8. Decays if you stop, so it reads as physically driving the round home.
const RAM_PER_PRESS_OK: f32 = 0.34;
const RAM_PER_PRESS_KO: f32 = 0.14;
const RAM_DECAY: f32 = 0.25;
/// A lone survivor (loader KO'd) must fumble the hot casing free before it ejects (assisted = instant).
const EJECT_FUMBLE: f32 = 0.8;
/// Extinguisher unclip time. Only foam deposited on a burning surface suppresses it.
const EXT_GRAB: f32 = 0.35;
/// The READY-RACK hotspot, turret-local — where the loader's crosshair must rest to grab a round
/// (shared by the hover test and `debug_loader_face_rack`).
const RACK_SPOT: Vec3 = Vec3::new(0.0, 1.83, 0.55); // legacy ready-rack point (headless aim helper)
                                                    // ── The PHYSICAL reload (user design: no auto-placement — you carry the weight) ─────────────────
                                                    // A grabbed round is a sprung mass on the hand anchor: it LAGS, swings, and droops — 13 kg of
                                                    // brass and shell. The ram only engages with the round bodily AT the tray mouth; the spent case
                                                    // must be PULLED from the breech and tossed by hand before anything can be loaded.
const TRAY_MOUTH: Vec3 = crate::interior_rig::ROUND_READY; // authored tray entrance / handoff pose
                                                           // The extinguisher bracket: Turret_0232's spot in the blend (rear-left wall, calibrated against
                                                           // ROUND_SEAT to 7 mm). The cylinder is excluded from the bake; the interactive bottle lives here.
const EXT_MOUNT_BASE: Vec3 = Vec3::new(-0.350, 0.848, -1.043);
const EXT_MOUNT_MID: Vec3 = Vec3::new(-0.350, 1.13, -1.043);
// ── The BREECH LEVER (user design 2026-07-06): pull UP to open the breech — only then can the
// hot case come out and a fresh round go in; pull DOWN after ramming to CLOSE, which is what
// completes the load. The gun fires only closed. Pivots calibrated from the blend (gun-local).
// The source gunner sight pupil is +0.493 m in the gun's X axis; place the mirrored lever
// on that same side of the block. The shared pivot also supplies the interaction target.
const GUNLEVER_POS: Vec3 = Vec3::new(0.252, -0.054, -0.987);
// The source cover has a curved upper cutout, so its overall AABB is not evidence that the
// chamber is covered. The raised closed pose is checked against rays across the brass base.
const BREECHCOVER_POS: Vec3 = Vec3::new(0.001, 0.132, -0.886);
const LEVER_SWING: f32 = 1.15; // rad about local X at full open (sign flipped: playtest said inverted)
const COVER_DROP: f32 = 0.362; // preserve the original fully-open endpoint at gun-local Y=-0.230
const LEVER_OPEN: f32 = 0.8; // open enough to work the breech
const LEVER_SHUT: f32 = 0.15; // closed enough to fire

/// One state drives both the visible reload lamp and its point light.
fn breech_indicator_state(breech: Breech, lever_open: f32, ready: bool) -> usize {
    if lever_open > LEVER_SHUT || !lever_open.is_finite() {
        1 // amber: open or still working the block, even with a seated live round
    } else if matches!(breech, Breech::Loaded) && ready {
        0 // green: closed, loaded and mechanically ready
    } else {
        2 // red: shut without a ready round, or the weapon is disabled
    }
}
                              // The HATCH LEVER on the cupola pedestal. Position extracted from the blend 2026-07-11:
                              // object 'Turret_0144' (data 'Hatch Lever') world (0.9596, 0.3358, 2.5622) minus Turret_Pivot
                              // (-0.0044, 0.0007, 0.4198), Blender->engine (bx, bz, -by). The old ESTIMATED value floated
                              // the knob ~40 cm off the pedestal, mid-compartment, right on the CUPOLA click anchor.
const HATCHLEVER_POS: Vec3 = Vec3::new(0.964, 2.142, -0.335);
const CUPOLA_HINGE: Vec3 = Vec3::new(0.963, 2.614, -0.333);

fn cupola_hatch_model(turret: Mat4, phase: f32) -> Mat4 {
    let lift = smoothstep(0.0, 0.5, phase) * 0.15;
    let swing = smoothstep(0.5, 1.0, phase) * (-110_f32).to_radians();
    turret * Mat4::from_translation(CUPOLA_HINGE + Vec3::Y * lift)
        * Mat4::from_rotation_y(swing)
}

fn cupola_hatch_lever_model(turret: Mat4, phase: f32) -> Mat4 {
    // The baked lid assembly includes the long stem down to this crank. Parent the separately
    // exported crank to that assembly so both ends of their joint lift and swing together.
    cupola_hatch_model(turret, phase) * Mat4::from_translation(HATCHLEVER_POS - CUPOLA_HINGE)
}
// Toolbox re-homed beside the extinguisher on the rear-left wall (playtest: it blocked the
// turret walk at its old spot). Hotspot at grab height; mesh sits just below it.
const TOOLBOX_MOUNT: Vec3 = Vec3::new(-0.75, 1.00, -0.98);
const TOOLBOX_MESH: Vec3 = Vec3::new(-0.75, 0.88, -0.98);
// The BREECH LAMP (user design): one annunciator-style lamp ON the breech, loader-side.
// GREEN = loaded & lever shut (ready) / ORANGE = lever open (reloading) / RED = shut on a
// spent case (or empty) — the reload cycle readable at a glance from anywhere in the turret.
const BREECH_LAMP_POS: Vec3 = Vec3::new(0.20, 0.12, -0.92); // gun-local, right of the block
const RAM_REACH: f32 = 1.55; // m — arm's reach to the authored tray mouth; crosshair gate does precision

fn gun_lever_model(gun_model: Mat4, lever_open: f32) -> Mat4 {
    gun_model * Mat4::from_translation(GUNLEVER_POS)
        * Mat4::from_rotation_x(LEVER_SWING * lever_open.clamp(0.0, 1.0))
}

fn breech_cover_model(gun_model: Mat4, lever_open: f32) -> Mat4 {
    // Match the physical action gates: the plate is fully shut whenever firing is permitted,
    // and fully clear as soon as extraction/loading is permitted.
    let opening = ((lever_open - LEVER_SHUT) / (LEVER_OPEN - LEVER_SHUT)).clamp(0.0, 1.0);
    gun_model * Mat4::from_translation(BREECHCOVER_POS - Vec3::Y * COVER_DROP * opening)
}

fn chambered_round_model(gun_model: Mat4) -> Mat4 {
    gun_model * Mat4::from_translation(crate::interior_rig::ROUND_SEAT - tank::TIGER_PARTS.gun_trunnion)
}

fn gunner_side_lever_mesh(mesh: crate::gltf_load::CpuMesh) -> crate::gltf_load::CpuMesh {
    let mut mesh = mesh.transformed(Mat4::from_scale(Vec3::new(-1.0, 1.0, 1.0)));
    // Reflection reverses handedness. Retain the original visible faces and normal-map basis.
    for triangle in mesh.indices.chunks_exact_mut(3) { triangle.swap(1, 2); }
    for vertex in &mut mesh.vertices { vertex.tangent[3] = -vertex.tangent[3]; }
    mesh
}

#[cfg(test)]
mod breech_geometry_tests {
    use super::*;

    fn first_hit(mesh: &crate::gltf_load::CpuMesh, origin: Vec3, direction: Vec3) -> Option<f32> {
        let mut nearest = f32::INFINITY;
        for triangle in mesh.indices.chunks_exact(3) {
            let [a, b, c] = [0, 1, 2].map(|i| Vec3::from(mesh.vertices[triangle[i] as usize].pos));
            let e1 = b - a;
            let e2 = c - a;
            let h = direction.cross(e2);
            let determinant = e1.dot(h);
            if determinant.abs() < 1e-10 { continue; }
            let s = origin - a;
            let u = s.dot(h) / determinant;
            let q = s.cross(e1);
            let v = direction.dot(q) / determinant;
            let distance = e2.dot(q) / determinant;
            if u >= -1e-5 && v >= -1e-5 && u + v <= 1.00001 && distance > 0.0 {
                nearest = nearest.min(distance);
            }
        }
        nearest.is_finite().then_some(nearest)
    }

    #[test]
    fn closed_source_block_covers_entire_brass_base_and_open_block_clears_it() {
        let cover = crate::gltf_load::load_glb("assets/tanks/tiger/baked/tiger_part_breechcover.glb").unwrap();
        for pitch in [-0.14_f32, 0.0, 0.26] {
            let gun = Mat4::from_translation(Vec3::new(14.0, 2.4, -7.0))
                * Mat4::from_rotation_y(0.73) * Mat4::from_rotation_x(pitch);
            for he in [false, true] {
                let round = round_88_mesh(he);
                let seated = chambered_round_model(gun);
                for opening in [0.0, LEVER_SHUT, LEVER_OPEN, 1.0] {
                    let inverse_cover = breech_cover_model(gun, opening).inverse();
                    for radius_fraction in [0.0, 0.35, 0.7, 1.0] {
                        for step in 0..24 {
                            let angle = step as f32 * std::f32::consts::TAU / 24.0;
                            let radius = round.max.x * radius_fraction;
                            let base = Vec3::new(radius * angle.cos(), radius * angle.sin(), round.min.z);
                            let destination = seated.transform_point3(base);
                            let origin = destination - gun.transform_vector3(Vec3::Z) * 1.0;
                            let local_origin = inverse_cover.transform_point3(origin);
                            let direction = inverse_cover.transform_vector3(gun.transform_vector3(Vec3::Z)).normalize();
                            let blocked = first_hit(&cover, local_origin, direction).is_some_and(|d| d < 1.0);
                            assert_eq!(blocked, opening <= LEVER_SHUT,
                                "cover failed at pitch={pitch}, opening={opening}, radius={radius}, angle={angle}");
                        }
                    }
                }
            }
        }
        let open = breech_cover_model(Mat4::IDENTITY, 1.0).transform_point3(Vec3::ZERO);
        assert!((open.y - (-0.018 - 0.212)).abs() < 1e-6,
            "retain the source's established fully-open block endpoint");
    }

    #[test]
    fn lever_moves_to_measured_sight_side_without_inverting_visible_faces() {
        let source = crate::gltf_load::load_glb("assets/tanks/tiger/baked/tiger_part_gunlever.glb").unwrap();
        let mirrored = gunner_side_lever_mesh(source.clone());
        let sight_local = tank::TIGER_SIGHT_EYEPIECE - tank::TIGER_PARTS.gun_trunnion;
        assert!(sight_local.x > 0.49 && GUNLEVER_POS.x > 0.0);
        for (&before, after) in source.vertices.iter().zip(&mirrored.vertices) {
            assert!(Vec3::from(after.pos).abs_diff_eq(Vec3::from(before.pos) * Vec3::new(-1.0, 1.0, 1.0), 1e-6));
            assert!((after.tangent[3] + before.tangent[3]).abs() < 1e-6);
        }
        for (before, after) in source.indices.chunks_exact(3).zip(mirrored.indices.chunks_exact(3)) {
            assert_eq!(after, &[before[0], before[2], before[1]]);
        }
        for opening in [0.0, 0.5, 1.0] {
            let transformed = mirrored.clone().transformed(gun_lever_model(Mat4::IDENTITY, opening));
            assert!(transformed.min.x > 0.11 && transformed.max.x < 0.27,
                "the complete lever must remain on the gunner sight side");
        }
    }

    #[test]
    fn seated_round_keeps_its_source_rest_pose_and_follows_gun_recoil_and_elevation() {
        let turret = Mat4::from_translation(Vec3::new(5.0, 0.7, -8.0)) * Mat4::from_rotation_y(0.53);
        let neutral_gun = turret * Mat4::from_translation(tank::TIGER_PARTS.gun_trunnion);
        assert!(chambered_round_model(neutral_gun).transform_point3(Vec3::ZERO)
            .abs_diff_eq(turret.transform_point3(crate::interior_rig::ROUND_SEAT), 1e-5));
        for pitch in [-0.14_f32, 0.26] {
            for recoil in [0.0, -0.25] {
                let gun = neutral_gun * Mat4::from_rotation_x(pitch)
                    * Mat4::from_translation(Vec3::Z * recoil);
                let local_seat = gun.inverse() * chambered_round_model(gun);
                assert!(local_seat.transform_point3(Vec3::ZERO).abs_diff_eq(
                    crate::interior_rig::ROUND_SEAT - tank::TIGER_PARTS.gun_trunnion, 1e-5));
                assert!(local_seat.transform_vector3(Vec3::Z).abs_diff_eq(Vec3::Z, 1e-5));
            }
        }
    }

    #[test]
    fn cupola_crank_joint_stays_attached_to_source_hatch_stem_during_lift_and_swing() {
        let hatch = crate::gltf_load::load_glb("assets/tanks/tiger/baked/tiger_hatch.glb").unwrap();
        let lever = crate::gltf_load::load_glb("assets/tanks/tiger/baked/tiger_part_hatchlever.glb").unwrap();
        let closed_hatch = cupola_hatch_model(Mat4::IDENTITY, 0.0);
        let closed_lever = cupola_hatch_lever_model(Mat4::IDENTITY, 0.0);
        assert!(closed_lever.abs_diff_eq(Mat4::from_translation(HATCHLEVER_POS), 1e-6));
        // Find a measured joint across the actual two independently exported meshes, not an
        // invented attachment point. Their source seam is about 1.2 mm when closed.
        let mut joint = (f32::INFINITY, Vec3::ZERO, Vec3::ZERO);
        for vertex in &hatch.vertices {
            let stem = Vec3::from(vertex.pos);
            if stem.y > hatch.min.y + 0.012 { continue; }
            for vertex in &lever.vertices {
                let crank = Vec3::from(vertex.pos);
                let gap = closed_hatch.transform_point3(stem).distance(closed_lever.transform_point3(crank));
                if gap < joint.0 { joint = (gap, stem, crank); }
            }
        }
        assert!(joint.0 < 0.002, "source stem and crank no longer share their measured joint");
        for yaw in [0.0, 0.8, 2.1] {
            let turret = Mat4::from_translation(Vec3::new(9.0, 0.5, -12.0)) * Mat4::from_rotation_y(yaw);
            for phase in [0.0, 0.25, 0.5, 0.75, 1.0] {
                let stem = cupola_hatch_model(turret, phase).transform_point3(joint.1);
                let crank = cupola_hatch_lever_model(turret, phase).transform_point3(joint.2);
                assert!((stem.distance(crank) - joint.0).abs() < 1e-5,
                    "cupola crank detached at yaw={yaw}, phase={phase}");
            }
        }
    }
}

fn manual_ram_eligible(breech: Breech, lever_open: f32, distance: f32, aim_dot: f32) -> bool {
    matches!(breech, Breech::Empty)
        && lever_open >= LEVER_OPEN
        && distance < RAM_REACH
        && aim_dot > 0.86
}

/// A short intentional flick in any direction drives the round. Mouse and right-stick look
/// share pixel-equivalent deltas, so distance/speed gates are independent of frame rate.
const RAM_FLICK_PIXELS: f32 = 28.0;
const RAM_FLICK_SPEED: f32 = 280.0;
fn ram_motion_fraction(dt: f32, motion: Vec2) -> f32 {
    if !dt.is_finite() || dt <= 0.0 || !motion.is_finite() { return 0.0; }
    let distance = motion.length();
    if distance / dt < RAM_FLICK_SPEED { 0.0 } else { (distance / RAM_FLICK_PIXELS).min(1.0) }
}

fn manual_ram_step(progress: f32, dt: f32, held: bool, eligible: bool, motion: Vec2) -> (f32, bool) {
    if !dt.is_finite() || dt <= 0.0 { return (progress, false); }
    if !held { return (0.0, false); }
    if !eligible { return ((progress - RAM_DECAY * dt).max(0.0), false); }
    // The completed gesture remains latched while the carried mesh physically settles into its
    // source chamber pose; release or losing the chamber still cancels it.
    if progress >= 1.0 { return (1.0, true); }
    let impulse = ram_motion_fraction(dt, motion);
    let next = if impulse > 0.0 { (progress + impulse).min(1.0) }
        else { (progress - RAM_DECAY * dt).max(0.0) };
    (next, impulse > 0.0 || next > 0.0)
}

/// One press works one complete detent. Holding the button or moving the mouse cannot toggle
/// back, and a round/case in either hand prevents moving the breech block through it.
fn breech_lever_click(open: f32, held: bool, was_held: bool, hands_free: bool) -> Option<f32> {
    (held && !was_held && hands_free).then_some(if open >= LEVER_OPEN { 0.0 } else { 1.0 })
}

fn round_grip_released(carrying: bool, held: bool) -> bool { carrying && !held }
fn equipped_tool_trigger(equipped: bool, held: bool, pickup_press: bool) -> bool {
    equipped && held && !pickup_press
}

const CARRY_K_ROUND: f32 = 48.0; // spring stiffness — heavy, visible lag
const CARRY_D_ROUND: f32 = 8.5;
const CARRY_K_CASE: f32 = 90.0; // the empty case is light — snappier in the hands
const CARRY_D_CASE: f32 = 11.0;
const CASING_PULL_TIME: f32 = 0.55; // s of held LMB to work the hot case out of the chamber

// Centre of the actual circular rear bore in the source `tiger_gun.glb` Breech mesh.
// Gun-local, so the case and its grip follow elevation and recoil with the breech.
const BREECH_CASE_BORE: Vec3 = Vec3::new(-0.000545, 0.07901, -1.06517);
const SPENT_CASE_RADIUS: f32 = crate::procedural_ordnance::CASE_MAX_DIAMETER_M * 0.5;
const SPENT_CASE_HALF_LENGTH: f32 = crate::procedural_ordnance::CASE_LENGTH_M * 0.5;
const CASE_EXTRACT_TRAVEL: f32 = 0.65;

fn spent_case_model(gun_model: Mat4, pull: f32) -> Mat4 {
    let centre = BREECH_CASE_BORE + Vec3::Z *
        (SPENT_CASE_HALF_LENGTH - 0.010 - CASE_EXTRACT_TRAVEL * pull.clamp(0.0, 1.0));
    gun_model * Mat4::from_translation(centre)
}

fn spent_case_grip(gun_model: Mat4, pull: f32) -> Vec3 {
    spent_case_model(gun_model, pull).transform_point3(-Vec3::Z * SPENT_CASE_HALF_LENGTH)
}

fn casing_extract_eligible(breech: Breech, lever_open: f32, hands_free: bool) -> bool {
    matches!(breech, Breech::Spent) && lever_open >= LEVER_OPEN && hands_free
}

fn casing_pull_step(progress: f32, dt: f32, held: bool, eligible: bool, aimed: bool) -> (f32, bool) {
    if !dt.is_finite() || dt <= 0.0 { return (progress, false); }
    // Once the hand grips the case it follows the extractor rather than re-acquiring a shrinking
    // moving target every frame. Releasing LMB or losing physical access cancels the grip.
    let gripping = held && eligible && (aimed || progress > 0.0);
    let next = if gripping { (progress + dt / CASING_PULL_TIME).min(1.0) }
        else { (progress - dt * 3.0).max(0.0) };
    (next, gripping)
}
// Two bounded instance pages: a dense 8 mm jet and persistent surface-owned deposited grains.
const N_FOAM: usize = surface_fire::MAX_DEPOSITS;
const N_FOAM_BATCHES: usize = 2;
const FOAM_FLYING_BATCH: usize = 0;
const FOAM_STUCK_BATCH: usize = 1;
const FOAM_RATE: f32 = surface_fire::EMISSION_RATE;
const FOAM_GRAIN_SIZE: f32 = surface_fire::GRAIN_M;
// Crew casualty blood: 8192 short-lived grains, each with its own complete physics state and exactly
// one visible cube instance. Four fixed 2048-instance colour batches keep split-screen rendering to
// four draws per view; measured source contacts populate a bounded connected surface film.
const N_BLOOD_CUBES: usize = 8192;
const BLOOD_VISUAL_DENSITY: usize = 8;
const N_BLOOD_BATCHES: usize = 4;
const BLOOD_GRAINS_PER_BATCH: usize = N_BLOOD_CUBES / N_BLOOD_BATCHES;
/// Every transient blood body is the same sand-grain voxel. Severity changes only how many grains
/// launch and how fast they travel; it never hides the effect inside a few oversized chunks.
const BLOOD_GRAIN_SIZE: f32 = surface_blood::GRAIN_M;
const N_BLOOD_STAINS: usize = surface_blood::MAX_CELLS;
const BLOOD_STAINS_PER_BATCH: usize = N_BLOOD_STAINS.div_ceil(N_BLOOD_BATCHES);
const TURRET_BLOOD_WALL_R: f32 = 1.04;
const TURRET_BLOOD_CEILING: f32 = 2.52;
const HULL_BLOOD_FLOOR: f32 = 0.38;
const HULL_BLOOD_CEILING: f32 = 1.74;
const HULL_BLOOD_MIN: Vec3 = Vec3::new(-1.24, HULL_BLOOD_FLOOR, 0.28);
const HULL_BLOOD_MAX: Vec3 = Vec3::new(1.24, HULL_BLOOD_CEILING, 2.30);
// Every incandescent grain is one collision-bearing terminal-ballistics body. The former 160-body
// macro shower plus 768 visual-only sparks is replaced by one bounded 768-body authority pool.
pub(crate) const N_HOT_FRAGMENTS: usize = 768;
const N_HOT_FRAGMENT_BATCHES: usize = 4;
const HOT_FRAGMENT_STAGE_CAPACITY: usize = N_HOT_FRAGMENTS;
const HOT_FRAGMENT_FIXED_DT: f32 = 1.0 / 480.0;
const HOT_FRAGMENT_MAX_STEP_M: f32 = 0.018;
const HOT_FRAGMENT_DAMAGE_MAX_S: f32 = 3.6;
const HOT_FRAGMENT_TAIL_MIN_SPEED: f32 = 1.2;
const HOT_FRAGMENT_TAIL_MAX_LENGTH: f32 = 0.145;
const HOT_FRAGMENT_TAIL_WIDTH_RATIO: f32 = 0.38;
// The visible temperature pages also define the radiance of the bounded fragment-swarm emitter.
// Emission is integrated from each real chip's six cube faces; the narrow history tail is only a
// motion representation of that same body and therefore contributes no duplicate source power.
const HOT_FRAGMENT_STAGE_COLOR: [Vec3; N_HOT_FRAGMENT_BATCHES] = [
    Vec3::new(1.0, 188.0 / 255.0, 78.0 / 255.0),
    Vec3::new(1.0, 116.0 / 255.0, 24.0 / 255.0),
    Vec3::new(225.0 / 255.0, 52.0 / 255.0, 9.0 / 255.0),
    Vec3::new(104.0 / 255.0, 14.0 / 255.0, 3.0 / 255.0),
];
const HOT_FRAGMENT_STAGE_EMISSIVE: [f32; N_HOT_FRAGMENT_BATCHES] = [2.45, 2.05, 1.05, 0.18];
// These pre-allocated scene slots are retained only to avoid re-indexing the large fixed scene while
// the renderer agent admits dynamic physical grains into the TLAS. They are submitted empty forever.
const N_MICRO_SPARK_BATCHES: usize = 3;
const RETIRED_MICRO_SLOT_CAPACITY: usize = 1;
/// Audio never needs hundreds of simultaneous one-shots. Retain a deterministic representative
/// subset plus the uncapped aggregate count, avoiding allocations and voice storms on a full hit.
pub const MAX_HOT_FRAGMENT_COLLISIONS_PER_FRAME: usize = 96;
/// A penetration gets two isolated contact voices, full stop. Hundreds of physical cubes may still
/// bounce visibly, but mixing dozens of simultaneous broadband contacts reads as clapping.
const MAX_HOT_FRAGMENT_AUDIO_CONTACTS: usize = 2;
