    #[test]
    fn second_discharge_never_force_lands_or_rewrites_the_first_projectile() {
        let first = AuthoritativeProjectile::new(
            41,
            ProjectileShooter::Player,
            &crate::ballistics::PZGR_39,
            Vec3::ZERO,
            Vec3::Z,
            1,
        );
        let mut pool = vec![first];
        let first_step = pool[0].swept_step(PROJECTILE_FIXED_DT);
        pool[0].commit_step(first_step);
        let first_before_second = pool[0].clone();
        pool.push(AuthoritativeProjectile::new(
            42,
            ProjectileShooter::Player,
            &crate::ballistics::PZGR_39,
            Vec3::ZERO,
            Vec3::Z,
            2,
        ));
        assert_eq!(pool.len(), 2);
        assert_eq!(pool[0].id, 41);
        assert_eq!(pool[0].pos, first_before_second.pos);
        assert_eq!(pool[0].distance_m, first_before_second.distance_m);

        let source = include_str!("game.rs");
        let live_fire = source
            .split("fn fire(&mut self, _r: &mut Renderer)")
            .nth(1)
            .and_then(|tail| tail.split("legacy_fire_trigger_time_disabled").next())
            .expect("live fire body remains inspectable");
        assert!(!live_fire.contains("land_player_shot"));
        assert!(!live_fire.contains("ray_sphere"));
    }

    fn projectile_state_after_schedule(schedule: &[f32]) -> AuthoritativeProjectile {
        let mut projectile = AuthoritativeProjectile::new(
            77,
            ProjectileShooter::Player,
            &crate::ballistics::PZGR_39,
            Vec3::ZERO,
            Vec3::Z,
            0xBEEF,
        );
        let mut accumulator = 0.0;
        for &frame_dt in schedule {
            accumulator += frame_dt;
            while accumulator + 1.0e-8 >= PROJECTILE_FIXED_DT {
                accumulator -= PROJECTILE_FIXED_DT;
                let step = projectile.swept_step(PROJECTILE_FIXED_DT);
                projectile.commit_step(step);
            }
        }
        projectile
    }

    #[test]
    fn projectile_time_and_drop_match_shellspec_at_500_and_1000_metres() {
        for range in [500.0, 1_000.0] {
            let shell = &crate::ballistics::PZGR_39;
            let mut projectile = AuthoritativeProjectile::new(
                range as u64,
                ProjectileShooter::Player,
                shell,
                Vec3::ZERO,
                Vec3::Z,
                5,
            );
            let mut prior = projectile.clone();
            while projectile.distance_m < range {
                prior = projectile.clone();
                let step = projectile.swept_step(PROJECTILE_FIXED_DT);
                projectile.commit_step(step);
            }
            let span = (projectile.distance_m - prior.distance_m).max(1.0e-6);
            let fraction = (range - prior.distance_m) / span;
            let time = prior.age_s + (projectile.age_s - prior.age_s) * fraction;
            let y = prior.pos.y + (projectile.pos.y - prior.pos.y) * fraction;
            assert!(
                (time - shell.time_of_flight(range)).abs() < 2.0e-4,
                "{range:.0} m TOF: {time} vs {}",
                shell.time_of_flight(range)
            );
            assert!(
                (-y - shell.drop_at(range)).abs() < 0.01,
                "{range:.0} m drop: {} vs {}",
                -y,
                shell.drop_at(range)
            );
        }
    }

    #[test]
    fn projectile_truth_is_identical_for_laptop_and_high_frame_schedules() {
        let laptop = projectile_state_after_schedule(&vec![1.0 / 30.0; 30]);
        let high = projectile_state_after_schedule(&vec![1.0 / 120.0; 120]);
        assert_eq!(laptop.id, high.id);
        assert_eq!(laptop.seed, high.seed);
        assert!((laptop.age_s - high.age_s).abs() < 1.0e-6);
        assert!((laptop.distance_m - high.distance_m).abs() < 1.0e-4);
        assert!(laptop.pos.distance(high.pos) < 1.0e-4);
        assert!(laptop.velocity.distance(high.velocity) < 1.0e-4);
    }

    #[test]
    fn live_enemy_discharge_has_one_report_without_a_close_range_duplicate() {
        let source=include_str!("game.rs");
        let live=source.split("fn enemy_fire(&mut self, i: usize)").nth(1)
            .and_then(|tail|tail.split("#[cfg(any())]").next()).unwrap();
        assert_eq!(live.matches("self.scheduled.push(").count(),1);
        assert_eq!(live.matches("synth_gun_report(").count(),1);
        assert!(!live.contains("self.schedule_sound_from("));
        // The surviving report keeps caliber, source, propagation and attenuation. Neither the
        // protected tank-MG identity nor the armor-hit family becomes a replacement muzzle cue.
        for retained in ["enemy_shell(kind).caliber_mm", "distance / SPEED_OF_SOUND",
            "SOUND_REF_DIST / (SOUND_REF_DIST + distance)", "source: muzzle", "buf: Some(report)"] {
            assert!(live.contains(retained),"lost discharge contract: {retained}");
        }
        assert!(!live.contains("TankMgShot"));assert!(!live.contains("synth_damage_impact"));
    }

    #[test]
    fn shipping_cannon_paths_exclude_legacy_spheres_and_random_turret_rolls() {
        let source = include_str!("game.rs");
        for signature in [
            "fn fire(&mut self, _r: &mut Renderer)",
            "fn enemy_fire(&mut self, i: usize)",
        ] {
            let body = source
                .split(signature)
                .nth(1)
                .and_then(|tail| tail.split("#[cfg(any())]").next())
                .expect("live cannon body remains inspectable");
            assert!(!body.contains("ray_sphere"), "legacy sphere in {signature}");
            assert!(
                !body.contains("0.42"),
                "random turret/hull band roll survived in {signature}"
            );
            assert!(body.contains("spawn_authoritative_projectile"));
        }

        let player_fx = source
            .split("struct Fx {")
            .nth(1)
            .and_then(|tail| tail.split("struct EnemyShot {").next())
            .expect("player tracer presentation remains inspectable");
        assert!(
            !player_fx.contains("pending_"),
            "player tracer retained fire-time terminal freight"
        );
        let enemy_fx = source
            .split("struct EnemyShot {")
            .nth(1)
            .and_then(|tail| tail.split("struct ScheduledSound {").next())
            .expect("external tracer presentation remains inspectable");
        for forbidden in ["outcome:", "hit_enemy:", "scar_facing:", "pending_"] {
            assert!(
                !enemy_fx.contains(forbidden),
                "external tracer retained terminal state: {forbidden}"
            );
        }
        assert!(
            source.contains("#[cfg(any())]\n                if frac >= 1.0"),
            "legacy tracer-landing consequence block must stay excluded from every build"
        );
    }

    fn test_vehicle_motion(id: usize, center: Vec2, heading: f32, velocity: Vec2) -> VehicleMotion {
        VehicleMotion {
            id,
            footprint: tank::HullFootprint {
                center,
                half_extents: Vec2::new(2.0, 3.0),
                heading,
            },
            velocity,
        }
    }

    #[test]
    fn vehicle_pair_resolution_splits_mtv_by_inverse_mass_and_separates() {
        let a = test_vehicle_motion(0, Vec2::ZERO, 0.0, Vec2::X);
        let b = test_vehicle_motion(1, Vec2::new(3.5, 0.0), 0.0, -Vec2::X);
        let resolution =
            vehicle_pair_resolution(a, 1.0, b, 1.0).expect("side overlap must resolve");
        assert!(resolution.closing);
        assert!((resolution.a_delta.x + (0.5 + VEHICLE_CONTACT_SLOP_M) * 0.5).abs() < 1e-6);
        assert!((resolution.b_delta.x - (0.5 + VEHICLE_CONTACT_SLOP_M) * 0.5).abs() < 1e-6);
        let separated_a = tank::HullFootprint {
            center: a.footprint.center + resolution.a_delta,
            ..a.footprint
        };
        let separated_b = tank::HullFootprint {
            center: b.footprint.center + resolution.b_delta,
            ..b.footprint
        };
        assert!(tank::yaw_obb_contact(separated_a, separated_b).is_none());
    }

    #[test]
    fn vehicle_pair_resolution_keeps_zero_inverse_mass_wreck_fixed() {
        let live = test_vehicle_motion(0, Vec2::ZERO, 0.0, Vec2::X);
        let wreck = test_vehicle_motion(1, Vec2::new(3.5, 0.0), 0.0, Vec2::ZERO);
        let resolution =
            vehicle_pair_resolution(live, 1.0, wreck, 0.0).expect("live/wreck overlap");
        assert_eq!(resolution.b_delta, Vec2::ZERO);
        assert!((resolution.a_delta.x + 0.5 + VEHICLE_CONTACT_SLOP_M).abs() < 1e-6);
    }

    #[test]
    fn vehicle_avoidance_brakes_and_breaks_head_on_tie_to_opposite_sides() {
        let a = test_vehicle_motion(0, Vec2::ZERO, 0.0, Vec2::new(0.0, 8.0));
        let b = test_vehicle_motion(
            1,
            Vec2::new(0.0, 12.0),
            std::f32::consts::PI,
            Vec2::new(0.0, -8.0),
        );
        let bodies = [a, b];
        let (a_drive, a_steer) = apply_vehicle_avoidance(a, &bodies, 1.0, 0.0);
        let (b_drive, b_steer) = apply_vehicle_avoidance(b, &bodies, 1.0, 0.0);
        assert!(a_drive < 1.0 && b_drive < 1.0);
        let a_world_dodge = Vec2::new(1.0, 0.0) * a_steer;
        let b_world_dodge = Vec2::new(-1.0, 0.0) * b_steer;
        assert!(
            a_world_dodge.dot(b_world_dodge) < 0.0,
            "opposite-facing hulls must choose opposite WORLD sides: {a_steer}, {b_steer}"
        );
    }

    #[test]
    fn vehicle_avoidance_coincident_centers_choose_finite_opposite_world_sides() {
        let a = test_vehicle_motion(2, Vec2::ZERO, 0.0, Vec2::ZERO);
        let b = test_vehicle_motion(9, Vec2::ZERO, 0.0, Vec2::ZERO);
        let bodies = [a, b];
        let (_, a_steer) = apply_vehicle_avoidance(a, &bodies, 0.5, 0.0);
        let (_, b_steer) = apply_vehicle_avoidance(b, &bodies, 0.5, 0.0);
        assert!(a_steer.is_finite() && b_steer.is_finite());
        assert!(a_steer * b_steer < 0.0);
    }

    #[test]
    fn vehicle_avoidance_leaves_safe_parallel_policy_action_unchanged() {
        let a = test_vehicle_motion(0, Vec2::ZERO, 0.0, Vec2::new(0.0, 7.0));
        let b = test_vehicle_motion(1, Vec2::new(9.0, 0.0), 0.0, Vec2::new(0.0, 7.0));
        let proposed = (0.72, -0.18);
        assert_eq!(
            apply_vehicle_avoidance(a, &[a, b], proposed.0, proposed.1),
            proposed
        );
    }

