    #[test]
    fn canonical_turret_crew_hit_centres_traverse_with_their_visible_figures() {
        let mut player = Tank {
            pos: Vec3::new(17.0, 2.0, -9.0),
            heading: 0.41,
            speed: 0.0,
            turret_yaw: 0.0,
            gun_pitch: 0.0,
            reload: 0.0,
            shot_age: crate::tank::GUN_RECOIL_END,
            alive: true,
            hp: tank::MAX_HP,
            parts: tank::TIGER_PARTS,
            kind: EnemyKind::T34,
        };
        let driver_before = crew_live_hit_center(&player, crate::lan::LanRole::Driver);
        let gunner_before = crew_live_hit_center(&player, crate::lan::LanRole::Gunner);

        // Engine +X is physical tank-left. Keep every visible post, camera-side damage centre and
        // takeover pose on the historical side of the breech.
        let turret_inv = player.turret_model().inverse();
        let hull_inv = player.hull_model().inverse();
        let local_origin = |post| {
            let parent_inv = match post {
                crate::lan::LanRole::Driver | crate::lan::LanRole::Radio => hull_inv,
                _ => turret_inv,
            };
            parent_inv.transform_point3(crew_live_model(&player, post).transform_point3(Vec3::ZERO))
        };
        let gunner_origin = local_origin(crate::lan::LanRole::Gunner);
        let loader_origin = local_origin(crate::lan::LanRole::Loader);
        let driver_origin = local_origin(crate::lan::LanRole::Driver);
        let radio_origin = local_origin(crate::lan::LanRole::Radio);
        assert!(gunner_origin.x > 0.0, "Gunner must be left of the breech");
        assert!(loader_origin.x < 0.0, "Loader must be right of the breech");
        assert!(driver_origin.x > 0.0, "Driver must be hull-left");
        assert!(radio_origin.x < 0.0, "Radio/MG operator must be hull-right");
        assert!(CrewRole::Gunner.station().x > 0.0);
        assert!(CrewRole::Loader.station().x < 0.0);

        let loader_local = turret_inv * crew_live_model(&player, crate::lan::LanRole::Loader);
        let loader_forward = loader_local.transform_vector3(Vec3::Z).normalize();
        let to_breech = ((crate::interior_rig::BREECH_MIN + crate::interior_rig::BREECH_MAX) * 0.5
            - loader_origin)
            * Vec3::new(1.0, 0.0, 1.0);
        let to_breech = to_breech.normalize();
        assert!(
            loader_forward.dot(to_breech) > 0.75,
            "Loader must face inward toward the breech"
        );

        let commander_local = turret_inv * crew_live_model(&player, crate::lan::LanRole::Commander);
        let commander_boots = commander_local.transform_point3(Vec3::ZERO);
        let commander_helmet = commander_local.transform_point3(Vec3::new(0.0, 1.53, 0.0));
        assert!((commander_boots.x - 0.564).abs() < 0.02);
        assert!((commander_boots.z + 0.423).abs() < 0.02);
        assert!((commander_boots.y - crate::interior_rig::FLOOR_STAND_Y).abs() < 1.0e-4);
        assert!(
            (2.35..2.457).contains(&commander_helmet.y),
            "upright Commander must stand beneath, not through, the cupola slit ring"
        );

        player.turret_yaw = std::f32::consts::FRAC_PI_2;
        let driver_after = crew_live_hit_center(&player, crate::lan::LanRole::Driver);
        let gunner_after = crew_live_hit_center(&player, crate::lan::LanRole::Gunner);

        assert!(driver_before.distance(driver_after) < 1.0e-5);
        assert!(gunner_before.distance(gunner_after) > 0.45);
        assert!((gunner_before.y - gunner_after.y).abs() < 1.0e-5);
    }

    #[test]
    #[cfg(any())] // superseded by tests/crew_ragdoll_physics.rs articulated-body contracts
    fn crew_ragdoll_launch_is_deterministic_and_follows_the_incoming_hit() {
        let player = Tank {
            pos: Vec3::new(17.0, 2.0, -9.0),
            heading: 0.41,
            speed: 0.0,
            turret_yaw: -0.27,
            gun_pitch: 0.0,
            reload: 0.0,
            shot_age: crate::tank::GUN_RECOIL_END,
            alive: true,
            hp: tank::MAX_HP,
            parts: tank::TIGER_PARTS,
            kind: EnemyKind::T34,
        };
        let casualty = CouchCrewCasualty {
            peer_id: 22,
            identity: crate::lan::LanRole::Gunner,
            role: crate::lan::LanRole::Gunner,
        };
        let local_hit = Vec3::new(-0.92, 0.08, 0.38).normalize();
        let world_hit = player
            .turret_model()
            .transform_vector3(local_hit)
            .normalize();
        let weak = new_crew_ragdoll(&player, casualty, world_hit, 0.35, 0xA11C_E551);
        let repeat = new_crew_ragdoll(&player, casualty, world_hit, 0.35, 0xA11C_E551);
        let violent = new_crew_ragdoll(&player, casualty, world_hit, 1.65, 0xA11C_E551);

        assert_eq!(weak.casualty, casualty);
        assert_eq!(weak.frame, BloodFrame::Turret);
        assert_eq!(weak.pos, repeat.pos);
        assert_eq!(weak.rot, repeat.rot);
        assert_eq!(weak.vel, repeat.vel);
        assert_eq!(weak.angular_vel, repeat.angular_vel);
        assert!(weak.vel.dot(local_hit) > 0.0);
        assert!(violent.vel.dot(local_hit) > weak.vel.dot(local_hit) + 0.01);
        assert!(
            violent.angular_vel.dot(violent.topple_axis)
                > weak.angular_vel.dot(weak.topple_axis) + 0.12
        );
        let body_axis = weak.rot * Vec3::Y;
        assert!(weak.angular_vel.dot(body_axis).abs() < 1.0e-5);

        let live_local = player.turret_model().inverse() * crew_live_model(&player, casualty.role);
        let (_, live_rot, live_origin) = live_local.to_scale_rotation_translation();
        let expected_center =
            live_origin + live_rot * Vec3::Y * (CREW_RAGDOLL_HALF_EXTENTS.y * weak.scale);
        assert!(weak.pos.distance(expected_center) < 1.0e-5);
    }

    #[test]
    #[cfg(any())] // superseded by tests/crew_ragdoll_physics.rs articulated-body contracts
    fn rigid_crew_body_bounces_settles_inside_hull_and_never_disappears() {
        let player = Tank {
            pos: Vec3::ZERO,
            heading: 0.0,
            speed: 0.0,
            turret_yaw: 0.0,
            gun_pitch: 0.0,
            reload: 0.0,
            shot_age: crate::tank::GUN_RECOIL_END,
            alive: true,
            hp: tank::MAX_HP,
            parts: tank::TIGER_PARTS,
            kind: EnemyKind::T34,
        };
        let casualty = CouchCrewCasualty {
            peer_id: 33,
            identity: crate::lan::LanRole::Driver,
            role: crate::lan::LanRole::Driver,
        };
        let mut body = new_crew_ragdoll(
            &player,
            casualty,
            Vec3::new(-0.95, 0.06, 0.30).normalize(),
            1.40,
            0xD21E_3300,
        );
        for _ in 0..1_200 {
            integrate_crew_ragdoll(&mut body, 1.0 / 120.0);
            if body.settled {
                break;
            }
        }

        assert!(
            body.settled,
            "the bounded rigid body must reach a permanent rest state"
        );
        assert!(
            body.bounces > 0,
            "the launch must visibly contact the cabin"
        );
        assert_eq!(body.vel, Vec3::ZERO);
        assert_eq!(body.angular_vel, Vec3::ZERO);
        let ext = crew_ragdoll_extents(&body);
        assert!(body
            .pos
            .cmpge(HULL_BLOOD_MIN + ext - Vec3::splat(1.0e-4))
            .all());
        assert!(body
            .pos
            .cmple(HULL_BLOOD_MAX - ext + Vec3::splat(1.0e-4))
            .all());
        assert!(
            (body.rot * Vec3::Y).dot(Vec3::Y).abs() < 0.72,
            "the non-articulated proxy must topple instead of balancing upright"
        );

        let frozen = (body.pos, body.rot, crew_ragdoll_model(&player, &body));
        for _ in 0..600 {
            integrate_crew_ragdoll(&mut body, 1.0 / 60.0);
        }
        assert_eq!(
            (body.pos, body.rot, crew_ragdoll_model(&player, &body)),
            frozen
        );
    }

    #[test]
    #[cfg(any())] // superseded by tests/crew_ragdoll_physics.rs articulated-body contracts
    fn rigid_crew_body_cannot_cross_the_solid_breech() {
        let casualty = CouchCrewCasualty {
            peer_id: 22,
            identity: crate::lan::LanRole::Gunner,
            role: crate::lan::LanRole::Gunner,
        };
        let mut body = CrewRagdoll {
            casualty,
            frame: BloodFrame::Turret,
            pos: Vec3::ZERO,
            rot: Quat::IDENTITY,
            vel: Vec3::new(9.0, 0.0, 0.0),
            angular_vel: Vec3::ZERO,
            scale: crew_ragdoll_scale(casualty.role),
            topple_axis: Vec3::Z,
            age: 0.0,
            quiet_t: 0.0,
            bounces: 0,
            settled: false,
        };
        let ext = crew_ragdoll_extents(&body);
        body.pos = Vec3::new(
            crate::interior_rig::BREECH_MIN.x - ext.x - 0.055,
            1.92,
            0.30,
        );
        integrate_crew_ragdoll(&mut body, 1.0 / 30.0);
        let ext_after = crew_ragdoll_extents(&body);
        assert!(body.bounces > 0);
        assert!(body.vel.x < 0.0, "the breech must throw the body back");
        assert!(
            body.pos.x <= crate::interior_rig::BREECH_MIN.x - ext_after.x + 1.0e-4,
            "the full oriented body must remain outside the expanded breech proxy"
        );
    }

