    #[test]
    fn high_speed_hot_steel_cannot_tunnel_through_breech_and_retires_bounded() {
        let radius = 0.03 * 0.52;
        let mut fragment = HotFragment {
            active: true,
            frame: BloodFrame::Turret,
            pos: Vec3::new(
                crate::interior_rig::BREECH_MIN.x - radius - 0.06,
                1.90,
                0.30,
            ),
            vel: Vec3::new(22.0, 0.0, 0.0),
            size: 0.03,
            spin: Vec3::splat(15.0),
            life: 1.1,
            ..HotFragment::default()
        };
        let mut collisions = Vec::new();
        let mut collision_count = 0;
        integrate_hot_fragment(
            &mut fragment,
            1.0 / 30.0,
            &mut collisions,
            &mut collision_count,
        );
        assert!(fragment.bounces >= 1, "swept substeps must find the breech");
        assert_eq!(collisions.len(), collision_count);
        assert!(collisions[0].speed >= 20.0);
        assert!(
            fragment.vel.x < 0.0,
            "steel must ricochet back from the block"
        );
        assert!(fragment.pos.x <= crate::interior_rig::BREECH_MIN.x - radius + 1.0e-4);
        for _ in 0..180 {
            integrate_hot_fragment(
                &mut fragment,
                1.0 / 120.0,
                &mut collisions,
                &mut collision_count,
            );
        }
        assert!(
            !fragment.active,
            "hot bodies must return to their fixed pool"
        );
    }

