    #[test]
    fn interior_fire_source_tracks_cell_area_radiance_centroid_and_extinction() {
        let cell = FireVoxelSample {
            offset: Vec3::new(0.03, 0.10, -0.02), rotation: Quat::IDENTITY,
            size: 0.020, stage: 0, generation: 0,
        };
        let origin = INTERIOR_FIRE_SPOTS[0];
        let parent = Mat4::from_translation(Vec3::new(3.0, 1.0, -2.0))
            * Mat4::from_rotation_y(0.7);
        assert!(interior_fire_aggregate_light(&[], origin, parent).is_none());
        let one = interior_fire_aggregate_light(&[cell], origin, parent).unwrap();
        // PointLight separates peak radiant intensity from normalized linear RGB. The red
        // base is below sRGB 255, so its texture's peak must participate in emitted power.
        let linear_color = Vec3::from_array(FIRE_FLAME_COLORS[0].map(|value|
            crate::rt_surface::srgb_to_linear(value as f32 / 255.0)));
        let peak_color = linear_color.max_element();
        let expected = peak_color * FIRE_FLAME_EMISSIVE[0] * 6.0 * cell.size.powi(2) / 4.0;
        assert!((one.radiant_intensity - expected).abs() < 1.0e-10);
        assert!(one.pos.distance(parent.transform_point3(origin + cell.offset)) < 1.0e-6);
        assert!((one.source_radius - cell.size * 0.5 * 3.0f32.sqrt()).abs() < 1.0e-6);
        assert!(one.color.distance(linear_color / peak_color) < 1.0e-6);

        let second = FireVoxelSample { offset: cell.offset + Vec3::X * 0.2, ..cell };
        let pair = interior_fire_aggregate_light(&[cell, second], origin, parent).unwrap();
        assert!((pair.radiant_intensity - one.radiant_intensity * 2.0).abs() < 1.0e-10);
        assert!(pair.pos.distance(parent.transform_point3(origin + cell.offset + Vec3::X * 0.1)) < 1.0e-6);
        assert!(pair.source_radius >= 0.1 + cell.size * 0.5 * 3.0f32.sqrt() - 1.0e-6);
        let larger = FireVoxelSample { size: cell.size * 2.0, ..cell };
        let scaled = interior_fire_aggregate_light(&[larger], origin, parent).unwrap();
        assert!((scaled.radiant_intensity - one.radiant_intensity * 4.0).abs() < 1.0e-10);
    }

    #[test]
    fn cabin_fire_keeps_amber_source_energy_separate_from_exterior_palette() {
        let cells: Vec<_> = (0..6144).map(|grain|
            flame_voxel_sample(0x51ed_19a1, grain, 0.25, 0.5, false)).collect();
        let source = interior_fire_aggregate_light(&cells, Vec3::ZERO, Mat4::IDENTITY).unwrap();
        // Check the actual aggregate, not just the brightest swatch: both visible flame pages
        // and their transported light must have a warm orange component after linearization.
        assert!(source.color.y / source.color.x > 0.20);
        assert!(source.color.y / source.color.x < 0.50);
        assert!(source.color.z / source.color.x < 0.05);
        assert!(source.radiant_intensity > 0.0 && source.radiant_intensity.is_finite());
        assert_eq!(&FIRE_FLAME_COLORS[FIRE_FLAME_STAGES..],
            &[[183, 24, 4], [255, 73, 6], [255, 107, 12], [203, 38, 6]]);
        assert_eq!(&FIRE_FLAME_EMISSIVE[FIRE_FLAME_STAGES..], &[0.8, 0.5, 0.25, 0.1]);
    }

    #[test]
    fn voxel_fire_is_axis_aligned_discrete_stacked_and_deterministic() {
        assert!(N_FIRE_FLAME_CUBES >= 768);
        assert!(N_FIRE_SMOKE_CUBES >= 480);
        assert_eq!(FIRE_FLAME_BATCHES + FIRE_SMOKE_BATCHES, 10);
        assert_eq!(INTERIOR_FIRE_SPOTS[0], Vec3::new(0.50, 1.70, -0.20));
        assert!(INTERIOR_FIRE_LIGHT_RADIUS <= 5.0);
        assert!(INTERIOR_FIRE_GLOW_RADIUS <= 1.4);

        let mut unique = std::collections::HashSet::new();
        let mut held_generation_pairs = 0usize;
        for grain in 0..FLAME_CUBES_PER_INTERIOR_SPOT {
            let a = flame_voxel_sample(0x51ed, grain, 2.75, 1.0, false);
            let b = flame_voxel_sample(0x51ed, grain, 2.75, 1.0, false);
            let held = flame_voxel_sample(0x51ed, grain, 2.751, 1.0, false);
            assert_eq!(a.offset, b.offset, "sampling must be replay deterministic");
            assert_eq!(a.rotation, Quat::IDENTITY);
            assert_eq!(b.rotation, Quat::IDENTITY);
            assert_eq!(a.size.to_bits(), b.size.to_bits());
            assert_eq!(a.stage, b.stage);
            assert_eq!(a.generation, b.generation);
            assert!((0.008..=0.010).contains(&a.size));
            assert!(a.size <= 0.010, "interior flame cells keep their own fixed 8–10 mm size");
            assert!(a.stage < FIRE_FLAME_BATCHES);
            // A cell does not drift, rotate or grow within one spawn lifetime. Only crossing the
            // discrete generation boundary is allowed to replace it.
            if a.generation == held.generation {
                held_generation_pairs += 1;
                assert_eq!(a.offset, held.offset);
                assert_eq!(a.rotation, held.rotation);
                assert_eq!(a.size.to_bits(), held.size.to_bits());
                assert_eq!(a.stage, held.stage);
            }
            unique.insert((
                a.offset.x.to_bits(),
                a.offset.y.to_bits(),
                a.offset.z.to_bits(),
            ));
        }
        assert!(
            unique.len() >= FLAME_CUBES_PER_INTERIOR_SPOT * 3 / 4,
            "the discrete stack needs broad cell occupancy even though intentional overlaps are allowed"
        );
        assert!(held_generation_pairs >= FLAME_CUBES_PER_INTERIOR_SPOT * 99 / 100);

        for grain in 0..SMOKE_CUBES_PER_INTERIOR_SPOT {
            let s = smoke_voxel_sample(0xc001, grain, 3.25, 1.0, false, Vec2::ZERO);
            assert!((0.0025..=0.0035).contains(&s.size));
            assert!(s.offset.y >= 0.46, "soot starts above the flame base");
            assert_eq!(s.rotation, Quat::IDENTITY);
            assert!(s.stage < FIRE_SMOKE_BATCHES);
        }
        let distant = flame_voxel_sample(7, 11, 1.0, 1.0, true);
        assert!(
            distant.size <= 0.230,
            "even distance-readable wreck grains stay far below the retired metre-wide boxes"
        );
        let distant_soot = smoke_voxel_sample(7, 11, 1.0, 1.0, true, Vec2::new(4.0, -2.0));
        assert!(distant_soot.size < distant.size);
        assert!(distant_soot.offset.y >= 1.82);
        assert_eq!(distant.rotation, Quat::IDENTITY);
        assert_eq!(distant_soot.rotation, Quat::IDENTITY);
    }

    #[test]
    fn fine_soot_density_grows_with_fire_without_multiplying_opaque_volume_per_patch() {
        assert_eq!(interior_soot_budget(1), 1536);
        for patches in 1..=N_INT_FIRE_SPOTS {
            assert!(interior_soot_budget(patches) * patches <= MAX_INTERIOR_SMOKE_CUBES);
        }
        assert_eq!(interior_soot_budget(32), 384);
        // Even the maximum-size total is much less opaque geometry than the former48 x32 x32mm.
        let new_volume = MAX_INTERIOR_SMOKE_CUBES as f32 * 0.0035_f32.powi(3);
        let old_volume = 48.0 * 32.0 * 0.032_f32.powi(3);
        assert!(new_volume < old_volume / 40.0);
        let mut occupied = std::collections::HashSet::new();
        for grain in 0..SMOKE_CUBES_PER_INTERIOR_SPOT {
            let a = smoke_voxel_sample(0xc001, grain, 2.0, 1.0, false, Vec2::ZERO);
            let b = smoke_voxel_sample(0xc001, grain, 2.0, 0.2, false, Vec2::ZERO);
            assert_eq!(a.size, b.size);
            assert_eq!(a.offset, b.offset);
            occupied.insert((a.offset.x.to_bits(), a.offset.y.to_bits(), a.offset.z.to_bits()));
        }
        assert!(occupied.len() > 340, "dense soot must not collapse to repeated coarse columns");
        for shader in [include_str!("../shaders/gbuf.wgsl"), include_str!("../shaders/mesh.wgsl")] {
            assert!(shader.contains("sparse_cubic_smoke && distance(in.world, cam.cam_pos) < 0.16"));
        }
    }

    #[test]
    fn breech_gas_is_a_light_finite_volume_not_a_cubic_soot_burst() {
        let early = breech_gas_sample(0.04).expect("gas attacks immediately");
        let body = breech_gas_sample(0.42).expect("gas remains visible while the block is open");
        let tail = breech_gas_sample(1.80).expect("a faint haze tail should linger");
        assert!(early.strength > 0.0 && early.strength < body.strength);
        assert!(body.strength <= 0.30, "bore gas must remain translucent");
        assert!(tail.strength < body.strength);
        assert_eq!(body.emitter, Vec3::new(0.0, 0.08, -1.06));
        assert!(body.direction.y > 0.0 && body.direction.z < -0.9);
        assert!(breech_gas_sample(BREECH_GAS_DUR).is_none());
        // The persistent fire pool now contains only actual flame/soot sources; opening a breech
        // cannot allocate or draw an opaque cube instance.
        assert_eq!(
            N_FIRE_SMOKE_CUBES,
            MAX_INTERIOR_SMOKE_CUBES + MAX_WORLD_FIRE_SOURCES * SMOKE_CUBES_PER_WORLD_SOURCE
        );
    }

    #[test]
    fn main_gun_camera_impulse_is_brief_bounded_and_split_view_safe() {
        let crew = main_gun_camera_sample(0.0, false, false);
        let optic = main_gun_camera_sample(0.0, true, false);
        let exposed = main_gun_camera_sample(0.0, false, true);
        assert!(crew.back <= 0.10 && crew.back > optic.back);
        assert!(exposed.back <= 0.16 && exposed.back > crew.back);
        for i in 0..=36 {
            let age = i as f32 * 0.01;
            let a = main_gun_camera_sample(age, false, false);
            let b = main_gun_camera_sample(age, false, false);
            assert_eq!(a.back.to_bits(), b.back.to_bits());
            assert_eq!(a.up.to_bits(), b.up.to_bits());
            assert_eq!(a.yaw.to_bits(), b.yaw.to_bits());
            assert_eq!(a.pitch.to_bits(), b.pitch.to_bits());
            assert!(a.back <= 0.10);
            assert!(a.up.abs() <= 0.012);
            assert!(a.yaw.abs() <= 0.009);
            assert!(a.pitch.abs() <= 0.050);
        }
        let done = main_gun_camera_sample(0.36, false, false);
        assert_eq!(done.back, 0.0);
        assert_eq!(done.up, 0.0);
        assert_eq!(done.yaw, 0.0);
        assert_eq!(done.pitch, 0.0);
    }

    #[test]
    fn repair_table_is_historically_sane() {
        use ModuleKind::*;
        // Field-fixable: tracks/transmission (slow, exposed), jams/stoppages/radio (quick).
        for k in [
            LeftTrack,
            RightTrack,
            Transmission,
            TurretTraverse,
            Radio,
            CoaxMg,
            HullMg,
        ] {
            assert!(repair_time(k).is_some(), "{k:?} should be a field-fix");
        }
        // Battle-destroyed / catastrophic — never a field-fix.
        for k in [MainGun, GunnerSight, Engine, Fuel, AmmoRack] {
            assert!(
                repair_time(k).is_none(),
                "{k:?} must NOT be repairable in the field"
            );
        }
        // A thrown track is the long, exposed job; clearing an MG stoppage is quick.
        assert!(repair_time(LeftTrack).unwrap() > repair_time(CoaxMg).unwrap());
    }

    #[test]
    fn replay_camera_pushes_from_shooter_toward_entry() {
        let s = Vec3::new(-260.0, 2.0, 30.0);
        let e = Vec3::new(0.0, 1.5, 0.0);
        let sd = (e - s).normalize();
        let (eye0, _) = replay_camera(s, e, sd, 0.0);
        let (eye1, _) = replay_camera(s, e, sd, 1.0);
        // Opens near the shooter, closes tight on the holed Tiger (the entry point).
        assert!(
            eye0.distance(s) < eye0.distance(e),
            "replay opens near the shooter"
        );
        assert!(
            eye1.distance(e) < eye1.distance(s),
            "replay closes on the entry"
        );
        // And it dollies inward, not outward, across the phase.
        assert!(
            eye1.distance(e) < eye0.distance(e),
            "the camera pushes in over the replay"
        );
    }

    #[test]
    fn interior_walk_clamps_to_floor_and_breech() {
        use crate::interior_rig as rig;
        // Stepping past the floor edge clamps inside the footprint (with body padding).
        let from = Vec3::new(0.5, 0.0, 0.0);
        let p = super::clamp_interior_walk(from, Vec3::new(5.0, 0.0, 5.0));
        assert!(
            p.x <= rig::FLOOR_MAX.x && p.z <= rig::FLOOR_MAX.z,
            "clamped to the floor: {p}"
        );
        // Walking straight at the breech from the loader's side stops or slides — never enters.
        let from = Vec3::new(0.6, 0.0, 0.3);
        let to = Vec3::new(0.0, 0.0, 0.3); // dead centre of the breech box
        let p = super::clamp_interior_walk(from, to);
        let pad = 0.15;
        let inside = p.x > rig::BREECH_MIN.x - pad
            && p.x < rig::BREECH_MAX.x + pad
            && p.z > rig::BREECH_MIN.z - pad
            && p.z < rig::BREECH_MAX.z + pad;
        assert!(!inside, "the breech blocks the body: {p}");
    }

    #[test]
    fn concussion_orders_caliber_penetration_and_distance() {
        let close_152_pen = concussion_severity(152.0, true, 0.5);
        let far_76_pen = concussion_severity(76.0, true, 3.0);
        let close_152_bounce = concussion_severity(152.0, false, 0.5);
        assert!(close_152_pen > far_76_pen);
        assert!(close_152_pen > close_152_bounce);
        assert!(close_152_pen >= 0.95);
        assert!(close_152_bounce <= 0.72);
    }

    #[test]
    fn armor_hit_camera_impulse_follows_shell_and_scales_physics() {
        // A shell travelling left-to-right into the Tiger must throw the eye right: away from its
        // source. Directional response is intentional, not randomized screen shake.
        let from_left = hit_camera_impulse(Vec3::X, 88.0, true, 0.8);
        assert!(from_left.x > 0.0);
        assert!(from_left.y.abs() < 1e-6 && from_left.z.abs() < 1e-6);

        let close_152_pen = hit_camera_impulse(Vec3::Z, 152.0, true, 0.5);
        let close_152_bounce = hit_camera_impulse(Vec3::Z, 152.0, false, 0.5);
        let far_76_pen = hit_camera_impulse(Vec3::Z, 76.0, true, 3.0);
        assert!(close_152_pen.length() > close_152_bounce.length());
        assert!(close_152_pen.length() > far_76_pen.length());
        assert_eq!(hit_camera_impulse(Vec3::ZERO, 152.0, true, 0.5), Vec3::ZERO);
    }

